WITH payload AS (SELECT $archive_payload$[{"id":"dd647e5f-1b94-5f73-bde8-2b4857b8066a","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع سيارة -فسخ البيع لوجود العيب -تقدير العيب عن طريق قسم اخلبراء -اليمن تشرع يف جانب أقوى املتداعين -حلف املدعى مين االستظهار -عند وجود العيب فللمشترى اخليار بن اإلمساك مع اإلرش أو الفسخ -احلكم بإلزام املدعى عليه تسليم الثمن وصرف النظر عن طلب الزيادة .","document_number":"33252287","case_number":"960","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالدمام","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/5/17","year":"1434","subject":"بيع سيارة -فسخ البيع لوجود العيب -تقدير العيب عن طريق قسم اخلبراء -اليمن تشرع يف جانب أقوى املتداعين -حلف املدعى مين االستظهار -عند وجود العيب فللمشترى اخليار بن اإلمساك مع اإلرش أو الفسخ -احلكم بإلزام املدعى عليه تسليم الثمن وصرف النظر عن طلب الزيادة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫تاريخه‪1433/5/17:‬هـ‬\n                     ‫ُ‬                  ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪33252287 :‬‬\n     ‫َر ْق ُم الدعوى‪ 960 :‬رقم قرار التصديق من محكمة‬\n           ‫االستئناف ‪ 344533:‬تاريخه‪1434/1/6 :‬هـ‬\n\n\n\n\n       ‫بيــع ســيارة ‪ -‬فســخ البيــع لوجــود العيــب ‪ -‬تقديــر العيــب عــن طريــق‬\n       ‫قســم اخلبــراء ‪ -‬اليمــن تشــرع يف جانــب أقــوى املتداعيــن ‪ -‬حلــف‬\n       ‫املدعــى ميــن االســتظهار ‪ -‬عنــد وجــود العيــب فللمشــترى اخليــار بــن‬\n       ‫اإلمســاك مــع اإلرش أو الفســخ ‪ -‬احلكــم بإلــزام املدعــى عليــه تســليم‬\n                                      ‫الثمــن وصــرف النظــر عــن طلــب الزيــادة ‪.‬‬\n\n\n\n                                             ‫اليمني تشرع يف جانب أقوى املتداعيني ‪.‬‬\n\n\n\n\n       ‫ادعــى املدعــي بأنــه اشــترى مــن الشــركة املدعــى عليها ســيارة موصوفة‬\n       ‫يف دعــواه وبعــد أن اســتخدمها ظهــر عيــب مصنعــي فيهــا مذكــور يف‬\n       ‫الدعــوى ‪ ،‬لــذا طلــب احلكــم علــى الشــركة املدعــى عليهــا بإبدالــه‬\n       ‫ســيارة مماثلــة وإذا تعــذر ذلــك إلزامهــا بإعــادة القيمــة ‪ -‬أنكــر وكيــل‬\n       ‫املدعــى عليهــا مــا جــاء يف الدعــوى مــن وجــود عيــب مصنعــي يف الســيارة‬\n       ‫ودفــع بــأن العطــل املذكــور يف دعــوى املدعــي نــاجت عــن عــدم اإللتــزام‬\n       ‫بقواعــد ســامة الســيارة بعــدم تغييــر زيــت احملــرك بانتظــام ‪ -‬مت فحــص‬\n       ‫الســيارة مــن قبــل اخلبــراء فــرأوا أن ســبب العيــب اخلطــأ يف التشــخيص‬\n       ‫مــن الشــركة وليــس عــدم اإلنتظــام يف تغييــر الزيــت‪ -‬قــررت احملكمــة‬\n\n‫‪27‬‬\n\f‫توجيــه ميــن االســتظهار للمدعــى عليــه على أن العيــب املذكور يف دعواه‬\n‫لــم يكــن بســبب ســوء اســتخدامه فــأدى اليمــن طبــق مــا طلــب منــه ‪-‬‬\n‫قضــت احملكمــة بإلــزام الشــركة املدعــى عليهــا أن تســلم املدعــي ثمــن‬\n‫الســيارة وصرفــت النظــر عمــا يطالــب بــه املدعــي زيــادة علــى ذلــك‪ -‬قنــع‬\n‫املدعــي باحلكــم وعارضــت عليــه املدعــى عليهــا ‪ -‬قــررت محكمــة‬\n                                         ‫االســتئناف املصادقــة علــى احلكــم ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد لــدي أنــا (‪ )....‬القاضي باحملكمــة العامة بالدمام‬\n‫ـاء علــى مــا وردنــا مــن فضيلــة الرئيــس برقــم ‪808‬يف ‪1431/01/25‬ه ـ‬        ‫بنـ ً‬\n‫حضــر(‪ )....‬ســعودي بالســجل املدنــي رقــم (‪ )....‬وادعــى علــى حاضــر معــه‬\n‫(‪ )....‬ســعودي بالســجل املدنــي رقــم (‪ )....‬الوكيــل عــن (‪ )....‬مبوجــب‬\n‫الوكالــة الصــادرة مــن عــدل الدمــام الثانيــة برقــم ‪ .............‬يف‬\n‫ا عــن‬  ‫‪1430/10/21‬ه ـ جلــد ‪ .....‬والوكيــل املذكــور بصفتــه وكي ـ ً‬\n‫(‪ )....‬مبوجــب الوكالــة الصــادرة مــن عــدل الدمــام الثانيــة برقــم ‪.....‬‬\n‫ا يف دعــواه‪:‬‬  ‫جلــد ‪ .....‬يف ‪1425/11/13‬ه ـ وادعــى علــى احلاضــر قائ ـ ً‬\n‫لقــد اشــتريت مــن شــركة (‪ )....‬للســيارات احملــدودة ســيارة مــن نــوع‬\n‫(‪ )....‬رقــم (‪ )....‬موديــل (‪ )....‬اللــون (‪ )....‬وتبــن فيهــا بعــض العيــوب‬\n‫املصنعيــة وهــي أن املكينــة (جيمــت) وال تعمــل وقــد كتــب ســابق ًا‬\n‫لبعــض الشــركات املتخصصــة للســيارات للكشــف عليــه وتقييــم‬\n‫وتبيــن عيبهــا فرفضــت (‪ )....‬وبعــض الشــركات وقــد قــررت كليــة‬\n‫التقنيــة مــا ذكرتــه لــذا أطلــب احلكــم علــى الشــركة املذكــورة‬\n‫بإبدالــي ســيارة نفــس النــوع مــن ذلــك النــوع مــن نفــس املوديــل وإذا تعــذر‬\n\n                                                                                       ‫‪28‬‬\n\f     ‫ذلــك إلزامهــم بإعــادة القيمــة وقيمتهــا قدرهــا مائــة وثمانــون ألــف ريــال‬\n     ‫هــذه دعــواي وبســؤال املدعــى عليــه أجــاب بقولــه أطلــب مهلــة لإلجابــة‬\n     ‫مفصلة يف اجللســة القادمة‪ .‬ويف جلســة أخرى يوم األحد ‪1432/4/29‬هـ‬\n     ‫افتتحــت اجللســة لــدى فضيلــة الشــيخ (‪ )....‬وفيهــا حضــر املدعــي وحضــر‬\n     ‫حلضــوره(‪ )....‬ســعودي بالســجل املدنــي رقــم (‪ )....‬الوكيــل الشــرعي‬\n     ‫لشــركة (‪ )....‬للســيارات احملــدودة مبوجــب الوكالــة الصــادرة مــن‬\n     ‫كتابــة عــدل الدمــام الثانيــة برقــم ‪ 29151‬يف ‪1427/5/14‬ه ـ جلــد‬\n     ‫‪ 5765‬وبســؤال املدعــى عليــه وكالــة عــن جوابــه علــى الدعــوى قــال‪:‬‬\n     ‫أطلــب إمهالــي للجــواب عنــا لدعــوى ورفعــت اجللســة‪ .‬ويف جلســة أخــرى‬\n     ‫يــوم االثنــن ‪1432/6/20‬ه ـ افتتحــت اجللســة وفيهــا حضــر (‪ )....‬وحضــر‬\n     ‫حلضــوره (‪ )....‬ســجل مدنــي رقــم (‪ )....‬الوكيــل الشــرعي عــن (‪)....‬‬\n     ‫الوكيــل الشــرعي عــن(‪ )....‬بصفتــه نائــب رئيــس مجلــس املديريــن‬\n     ‫لشــركة (‪ )....‬للســيارات املخولــة لــه حــق اإلجابــة واملرافعــة واملدافعــة‬\n     ‫واإلقــرار واإلنــكار الصــادرة مــن كتابــة عــدل الدمــام الثانيــة رقــم‬\n     ‫‪ 14416‬يف ‪1432/03/24‬ه ـ وبســؤاله عــن جوابــه عــن الدعــوى قــال‪:‬‬\n     ‫أقــدم لفضيلتكــم جوابــي محــرر ًا علــى مطبوعــات شــركة (‪)....‬‬\n     ‫للســيارات بتاريــخ ‪1432/6/20‬ه ـ املوافــق ‪2011/05/23‬م ونــص‬\n     ‫املقصــود مــن الــرد أن مــا تضمنتــه الئحــة املدعــي بــأن الســيارة مــن نــوع‬\n     ‫ا مصنعي ـ ًا وأنــه كان ملتــزم بجميــع‬     ‫(‪ )....‬موديــل (‪ )....‬بــأن بهــا خل ـ ً‬\n     ‫التشــييكات الدوريــة وكذلــك التغييــرات الدوريــة اخلاصــة بزيــت‬\n     ‫احملــرك بهــذا نفيــد فضيلتكــم بــأن مــا ذكــره املدعــي غيــر صحيــح‬\n     ‫وأنــه يخالــف ويناقــض املســتندات (الفواتيــر) التــي تقــدم بهــا للمحكمــة‬\n     ‫والتــي تثبــت أن مــا ذكــره املدعــي غيــر صحيــح لــم يكــن منتظم ـ ًا يف‬\n\n\n‫‪29‬‬\n\f‫تغييــر الزيــت فاملدعــي قــدم خمســة فواتيــر أقدمهــا تاريخ ـ ًا هــو أول‬\n‫تغييــر للزيــت يف الســيارة منــذ اســتالمها كان بتاريــخ ‪2006/10/31‬م‬\n‫وحينهــا كانــت الســيارة قــدم شــيت مســافة ‪ 16000‬كيلــو متــر ًا أي أنــه‬\n‫مت تغييــر الزيــت بعــد أن قطعــت الســيارة ‪7500‬كيلــو متــر ًا والفاتــورة‬\n‫التــي تليهــا كانــت بتاريــخ ‪ 2007/4/21‬وعندهــا كانــت الســيارة‬\n‫حســب البيانــات املســجلة علــى الفاتــورة قــد مشــيت مســافة ‪ 13984‬ويف‬\n‫هــذا يالحــظ تناقــض واضــح بــن الفاتورتــن وســوف نناقشــها يف فقــرة‬\n‫منفصلــة والفاتــورة التاليــة لهــا كانــت بتاريــخ ‪2008/1/13‬م وعندهــا‬\n‫كانــت الســيارة قــد قطعــت ‪ 30000‬كيلــو متــر ًا أي بعــد أن مشــيت‬\n‫الســيارة مســافة ‪ 14000‬كيلــو متــر ًا والفاتــورة األخيــرة كانــت بتاريــخ‬\n‫‪2008/4/27‬موعندهــا كانــت الســيارة قــد قطعــت مســافة ‪47229‬‬\n‫كيلومتــر ًا أي بعــد أن قطعــت الســيارة بعــد آخــر تغييــر للزيــت مســافة‬\n‫‪ 17229‬كيلومتــر ًا فــا يخفــى علــى فضيلتكــم أن املدعــي كان غيــر‬\n‫منتظـ ٍـم بقواعــد ســامة الســيارة ومنهــا تغييــر الزيــت حســب تعليمــات‬\n‫الوكيــل فهــو كان يتجــاوز املســافة التــي يتوجــب عليهــا تغييــر الزيــت‬\n‫بأضعافهــا وأحيانـ ًا إلــى ثالثــة أضعــاف كمــا يف التغييــر األخيــر إن هــذه‬\n‫املعلومــات واحلقائــق والتناقضــات املأخــوذة مــن الفواتيــر التــي قدمهــا‬\n‫املدعــي بنفســه كبينــة لــه يجــب أن تنقلــب إلــى ضــده لتكــون بينــة عليــه‬\n‫لألســباب التاليــة‪ :‬أ‪ -‬عــدم التــزام املدعــي بالتعليمــات اخلاصــة بســامة‬\n‫محــرك الســيارة ومنهــا تغييــر الزيــت عنــد كل ‪5000‬كيلومتــر تقطعهــا‬\n‫الســيارة فكمــا أســلفنا أن الفواتيــر التــي قدمهــا املدعــي كبينــة علــى‬\n‫أنــه كان يقــوم بتغييــر زيــت محــرك الســيارة بانتظــام تثبــت أنــه كان‬\n‫يتجــاوز املســافة احملــددة إلــى أكثــر مــن ثالثــة أضعافهــا أحيانــا ب‪ -‬إن‬\n\n\n                                                                                   ‫‪30‬‬\n\f     ‫التضــارب املوجــود بــن الفاتورتــن الثانيــة والثالثــة والتــي تثبــت أن‬\n     ‫الســيارة كانــت قــد قطعــت يف تاريــخ ‪2007/01/23‬ممســافة ‪16000‬‬\n     ‫كيلومتــر ًا بينمــا يف ‪2007/04/21‬م تناقصــت املســافة التــي قطعتهــا‬\n     ‫الســيارة إلــى ‪ 13984‬فهــذا التناقــض العجيــب ليــس لــه تفســير ســوى أن‬\n     ‫املدعــي كان يتالعــب بعــداد الســيارة اخلاصــة باملســافة التــي تقطعهــا‬\n     ‫الســيارة إمــا إلخفــاء حقيقــة أنــه كان يتجــاوز املســافة التــي كانــت‬\n     ‫تقطعهــا الســيارة بــن كل تغييــر لزيــت احملــرك إلخفــاء جتــاوزه املســافة‬\n     ‫املســموح بهــا أو لزيــادة فتــرة الضمــان املمنوحــة لهــا بإنقــاص املســافة‬\n     ‫التــي قطعتهــا الســيارة وهــذا يجعلنــا نشــك يف مصداقيــة املدعــي ويلقــي‬\n     ‫بظــال كثيفــة علــى كل أقوالــه وادعاءاتــه يف الدعــوى األمــر الــذي‬\n     ‫يســتلزم علــى احملكمــة أن تضــع يف االعتبــار هــذه احلقائــق والتناقضــات‬\n     ‫عنــد احلكــم يف الدعــوى ولــكل مــا تقــدم نلتمــس مــن فضيلتكــم رد‬\n     ‫الدعــوى لعــدم صحــة ادعــاء املدعــي ولعــدم اســتنادها إلــى بينــات تثبــت‬\n     ‫صحــة دعــواه الوكيــل الشــرعي (‪ )....‬توقيعــه وبــرد مــا جــاء يف املذكــرة‬\n     ‫علــى املدعــي طلــب إمهالــه لتقــدمي رده أو جوابــه محــرر ًا عليــه فقــد رفعــت‬\n     ‫اجللســة‪ .‬ويف جلســة أخــرى يــوم األثنــن ‪1432/7/18‬ه ـ افتتحــت اجللســة‬\n     ‫وفيهــا حضــر املدعــي (‪ )....‬وحضــر حلضــوره(‪ )....‬املذكــورة هويتــه‬\n     ‫بعاليــه وبســؤال املدعــي عــن جوابــه قــدم ورقــة نصهــا كالتالــي‪( :‬إشــارة‬\n     ‫إلــى املذكــرة املقدمــة مــن قبــل املدعــى عليهــا شــركة (‪ )....‬للســيارات‬\n     ‫بتاريــخ ‪20‬جمــادى الثانــي ‪1432‬ه ـ والتــي ذكــرت فيهــا مبــررات واهيــة‬\n     ‫بهــدف التهــرب مــن إقــرار احلقــوه و تعويضــي بســيارة جديــدة مت التصالــح‬\n     ‫عليــه لــدى فضيلــة القاضــي الســابق وهــو تعويضــي بســيارة جديــدة‬\n     ‫ا حيــث مت منحــي ســيارة مســتعملة لالســتخدام‬          ‫وبدأنــا يف التنفيــذ فع ـ ً‬\n\n\n‫‪31‬‬\n\f‫ـاء‬\n‫املؤقــت بــدل الضــرر حتــى التعويــض الكامــل عــن الســيارة وذلــك بنـ ً‬\n‫علــى توجيهــات القاضــي وهــذا مت تنفيــذه إال أن الوكالــة ســحبت‬\n‫الســيارة بعــد مضــي فتــرة علــى التنفيــذ وذلــك بعدمــا تغيــر القاضــي لــذا‬\n‫نرغــب يف ذكــر بعــض النقــاط الواضحــة رد ًا علــى املذكــرة ونوجزهــا‬\n‫يف مــا يلــي‪-1 :‬التشــييك وتغييــر الزيــت التزمت منذ بداية شــراء الســيارة‬\n‫بالتشــييك حســب تعليمــات الوكالــة وطــوال الفتــرة األولــى مــن‬\n‫املراجعــات املســتمرة بســبب اخللــل الــذي طــرأ علــى الســيارة لــم يتحــدث‬\n‫أحــد أبــد ًا عــن عــدم التزامــي بالتشــييك ومــن جهــة أخــرى إننــي تقدمــت‬\n‫إلــى احملكمــة بهــذه الفواتيــر حســب املتوفــر لــدي ومــا هــو محفــوظ‬\n‫عنــدي وميكــن أنتكــون الفواتيــر واملراجعــات أكثــر مــن هــذا وكان‬\n‫مــن املفــروض أن تتقــدم الشــركة بكشــف مفصــل لعــدد املراجعــات‬\n‫حيــث إنهــا حتتفــظ بالتفاصيــل ولديهــا يف ســجالت إلكترونيــة ولكني‬\n‫تبــن لفضيلتكــم عــدم التــزام الشــركة بالتســجيل املقــن حيــث إن‬\n‫بعــض الفواتيــر كتبــت باليــد لــم تكــن القــراءة صحيحــة والدليــل علــى‬\n‫جزافيــة القــراءة هــو العــدد الكامــل يف تلــك الفاتورتــن فقــط املكتوبــة‬\n‫باليــد وهــي ‪ 16000‬ويف القــراءة التاليــة ‪ 30000‬وهــذا يبــن عــدم الدقــة‬\n‫يف القــراءة مثــل باقــي املــرات املســجلة بشــكل صحيــح‪ -2.‬التناقــض‬\n‫بــن الفاتورتــن فقــد ورد يف مذكــرة الشــركة بــأن هــذا التناقــض بــن‬\n‫القــراءات وانخفــاض قــراءة العــداد دليــل علــى التالعــب فيــه وهــذا يعنــي‬\n‫االتهــام بالتزويــر لــذا نطلــب مــن فضيلتكــم إحالــة الســيارة إلــى جلنــة‬\n‫اخلبــراء لكــي تبــن وجــود التالعــب مــن عدمــه وهــذا اتهــام ال أقبلــه‬\n‫حيــث إنــه طعــن يف شــريف ونزاهتــي ولكــي يتبــن بــأن مــن قصــد‬\n‫التالعــب هــو مــن كتــب القــراءة جزاف ـ ًا بهــدف التهــرب مــن اإلصــاح‬\n\n\n                                                                                    ‫‪32‬‬\n\f     ‫والضمــان وليــس العكــس فهــل مــن طلــب احلــق يعتبــر مدلــس ومــزور؟‪.‬‬\n     ‫‪ -3‬لــو أخذنــا تاريــخ الشــراء وهــو ‪2006/8‬م إلــى آخــر قــراءة يف الفواتيــر‬\n     ‫وهــي ‪ 47229‬كلــم بتاريــخ ‪2008/4‬م يتبــن لنــا بــأن متوســط ســير‬\n     ‫الســيارة خالل‪20‬شــهر ًا هــو ‪ 23600‬كلــم وهــذا يعنــي بــأن القــراءة‬\n     ‫الثانيــة والتــي قفــزت إلــى ‪ 16000‬خــال أربعــة أشــهر غيــر صحيحــة‬\n     ‫وغيــر مناســبة إطالقــا ‪ -4‬لقــد أوردت املدعــى عليهــا بــأن التعليمــات‬\n     ‫بســامة احملــرك هــو ‪ 5000‬كلــم ولــو افترضنــا بــأن الفواتيــر اخلمــس‬\n     ‫املقدمــة هــي جميــع مــا مت تشــييكه علــى الرغــم بأنــي لــم احتفــظ‬\n     ‫بجميعهــا فــإن التعليمــات الصــادرة مــن الوكالــة حســب الكتيب املرفق‬\n     ‫باســم املواعيــد احملــددة لصيانــة زيــت احملــرك هــو عشــرة آالف وهــذا‬\n     ‫يعنــي بــأن التأخيــر يف هــذه احلــدود ال يســبب ضــرر ًا علــى الســيارة ويــؤدي‬\n     ‫بهــا إلــى اخلــراب الغيــر طبيعــي والــذي تســبب يف املشــكلة علــى الرغــم‬\n     ‫بعــدم قبــول احملكــم وهــو الكليــة التقنيــة بهــذا الــرأي‪ .‬أخيــر ًا إننــي‬\n     ‫أمتســك بقــرار الكليــة التقنيــة فقــد أحيلــت القضيــة إلــى اللجنــة بنــاء‬\n     ‫علــى طلــب املدعــى عليهــا وبكامــل إرادتهــا فقــد صاغــت اللجنــة قرارها‬\n     ‫بوضــوح وبــكل حياديــة بــأن الســبب لــم يكــن تغييــر الزيــت ولكــن‬\n     ‫هنــاك خطــأ مصنعــي فيجــب التعويــض وحيث إن الشــركة هــي اخلاطئة‬\n     ‫يف التشــخيص حســب التقريــر فقــد حتملــت أتعــاب اللجنــة ونحــن‬\n     ‫نتمســك بهــذا القــرار ويجــب أن تتحمــل تعويضنــا باألضــرار الناجمــة عــن‬\n     ‫هــذا اخلطــأ‪ .‬أ‪.‬ه ـ عليــه فقــد رفعــت اجللســة‪ .‬ويف جلســة أخــرى يــوم االثنــن‬\n     ‫‪1432/11/19‬ه ــافتتحت اجللســة وفيهــا حضــر املدعــي وحضــر حلضــوره‬\n     ‫(‪ )....‬الوكيــل الشــرعي عــن شــركة(‪ )....‬للســيارات احملــدودة وبســؤال‬\n     ‫املدعــى عليــه وكالــة عــن جوابــه قــال‪ :‬لــم يســلمني املوظــف املذكــرة‬\n\n\n‫‪33‬‬\n\f‫ـاء عليــه فقــد جــرى تســليمه املذكــرة يف‬       ‫التــي أبرزهــا املدعــي فبنـ ً‬\n‫مجلــس احلكــم مباشــرة ورفعــت اجللســة لذلــك‪ .‬ويف جلســة أخــرى يــوم‬\n‫الثالثــاء ‪1432/11/27‬ه ـ افتتحــت اجللســة وفيهــا حضــر املدعي وحضر‬\n‫حلضــوره (‪ )....‬الوكيــل الشــرعي عــن شــركة (‪ )....‬للســيارات احملــدودة‬\n‫وبســؤاله عــن جوابــه قــال‪ :‬لــم اســتطع إعــداد جوابــي يف هــذه اجللســة‬\n‫نظــر ًا لنســياني املوعــد وأطلــب إمهالــي إلــى اجللســة القادمــة وعليــه فقــد‬\n‫رفعــت اجللســة لذلــك‪ .‬ويف جلســة أخــرى يــوم الســبت املوافــق‬\n‫‪1432/12/23‬ه ـ افتتحــت اجللســة وفيهــا حضــر الطرفــان وســبق أن‬\n‫رفعــت اجللســة ألجــل إحضــار جــواب املدعــى عليــه علــى الدعوى وبســؤال‬\n‫املدعــى عليــه عــن جوابــه الــذي وعــد بــه أبــرز ورقــة نــص املقصــود منهــا‪:‬‬\n‫إشــارة إلــى املذكــرة املقدمــة مــن املدعــي بتاريــخ ‪1432/11/17‬ه ــوإلى‬\n‫التقريــر الفنــي الصــادر مــن قبــل الكليــة التقنيــة بالدمــام بخصــوص‬\n‫الســيارة مــن نــوع (‪ )....‬موديــل (‪ )....‬ذات اللوحــة رقــم (‪ )....‬والتــي تعتبــر‬\n‫محل الدعوى املقامة منا ملدعي ضد موكلتي شــركة (‪ )....‬للســيارات‬\n‫أقــدم لفضيلتكــم نيابــة عــن املدعــى عليهــا ردنــا الــذي يتضمــن التعقيــب‬\n‫علــى مــا ذكرتــه وكذلــك رفضنــا للتقريــر الصــادر مــن الكليــة التقنية‬\n‫علــى النحــو التالــي‪ :‬أوالً‪ :‬إن موكلتــي ترفــض التقريــر الفنــي الصــادر‬\n‫منــا لكليــة التقنيــة وتطالــب احملكمــة املوقــرة بتجاهلــه وذلــك ملــا‬\n‫يلــي‪ -1:‬لقــد خرجــت اللجنــة الفنيــة التابعــة للكليــة التقنيــة بالدمــام‬\n‫والتــي كلفــت بوضــع التقريــر الفنــي عبــر مهمتهــا األساســية وهــي‬\n‫اإلفــادة عــن احلالــة الفنيــة للســيارة ‪ ..‬إلــى هنــا وقــد رفعتــا جللســة لرغبــة‬\n‫وكيــل (‪ )....‬يف موعــد آخــر وعليــه رفعــت اجللســة الســتكمال مذكرته‬\n‫التــي قدمهــا يف جلســة أخــرى‪ .‬ويف يــوم األحــد ‪1433/02/07‬ه ـ لــدي أنا‬\n\n\n                                                                                          ‫‪34‬‬\n\f     ‫(‪ )....‬القاضــي اخللــف لفضيلــة الشــيخ (‪ )....‬القاضــي األســبق بهــذه‬\n     ‫احملكمــة افتتحــت اجللســة وفيهــا حضــر الطرفــان وقــد جــرى تــاوة مــا‬\n     ‫ســبق ضبطــه يف اجللســات الســابقة عليهمــا فصادقــا علــى صحتــه كل‬\n     ‫مبــا يخصــه ولكثــرة لفــات املعاملــة فقــد جــرى رفــع اجللســة لدراســتها‬\n     ‫بعــد إعــام الطرفــن باحلضــور يــوم الســبت املوافــق ‪1433/02/13‬ه ـ‬\n     ‫ويف جلســة أخــرى يــوم الســبت ‪1433/02/13‬ه ـ افتتحــت اجللســة وفيهــا‬\n     ‫حضــر الطرفــان وبطلــب حتريــر الدعــوى مــن املدعــي قــال‪ :‬إننــي أطلــب‬\n     ‫إلــزام املدعــى عليــه بتســليمي قيمــة آخــر موديــل منــوع الســيارة التــي‬\n     ‫حصــل فيهــا عيــب مصنعــي وســحبت منــي التــي ذكرتهــا يف أول دعــواي‬\n     ‫وهــو موديــل (‪ )....‬وقيمتهــا يف الســوق مائتــان وخمســة عشــر ألــف ريــال‬\n     ‫أطلــب إلــزام الشــركة بتســليمي هــذا املبلــغ هــذه دعــواي وبســؤال‬\n     ‫املدعــى عليــه وكالــة عمــا جــاء يف دعــوى املدعــي قــال‪ :‬مــا ذكــره‬\n     ‫املدعــي يف دعــواه مــن شــرائه منــا الســيارة التــي ذكــر بعاليــه بالقيمــة‬\n     ‫املذكــورة فهــذا صحيــح وأمــا مــا ذكــره مــن أنــه وجــد يف الســيارة عيــب‬\n     ‫مصنعــي فهــذا غيــر صحيــح وإمنــا الــذي حصــل خلــل يف املاكينــة بســبب‬\n     ‫عــدم انتظامــه يف التشــييكات وتغييــر الزيــت يف موعــده لــدى الشــركة‬\n     ‫هكــذا قــرر وبعــرض ذلــك علــى املدعــي قــال‪ :‬بــل الــذي يف الســيارة خلــل‬\n     ‫مصنعــي وأنــا منتظــم لــدى الشــركة يف جميــع التشــييكات وتغييــر‬\n     ‫الزيــت يف موعــده وبســؤال املدعــي عــن وضــع الســيارة اآلن قــال‪ :‬إنهــا‬\n     ‫تالفــة وقــد أخــذوا منهــا بعــض قطــع الغيــار وبعــرض ذلــك علــى املدعــى‬\n     ‫عليــه قــال‪ :‬أنــا ال أدري هــل أخــذوا منهــا شــيئ ًا أو ال وأطلــب رفــع اجللســة‬\n     ‫للرجــوع إلــى الشــركة ورفعــت اجللســة لذلــك‪ .‬ويف جلســة أخــرى يــوم‬\n     ‫الثالثــاء املوافــق‪ 1433/02/23‬ه ـ افتتحــت اجللســة وفيهــا حضــر‬\n\n\n‫‪35‬‬\n\f‫املدعــي(‪ )....‬وحضــر حلضــوره (‪ )....‬الوكيــل الشــرعي عــن شــركة (‪)....‬‬\n‫للســيارات احملــدودة املذكــورة هويتــه بعاليــه وبســؤال املدعــى عليــه‬\n‫وكالــة عمــا طلــب رفــع اجللســة مــن أجلــه قــال‪ :‬إن الســيارة بحالهــا ولــم‬\n‫تأخــذ الشــركة منهــا شــيئ ًا غيــر أن املاكينــة مــا زالــت مفتوحــة ولــم‬\n‫تركــب بعدمــا مت فتحهــا مــن قبــل الكليــة التقنيــة وبعــرض ذلــك علــى‬\n‫املدعــي قــال‪ :‬بــل أخــذوا منــه أوال أدري عــن القطــع التــي أخذوهــا‬\n‫وبســؤاله هــل لديــه بينــة علــى ذلــك قــال‪ :‬نعــم كمــا أننــي قــد وجــدت يف‬\n‫اجللســة التــي بتاريــخ ‪1432/07/18‬ه ـ كالم املدعــي أنــه مت التصالــح‬\n‫لــدى فضيلــة القاضــي الســابق علــى تعويضــه بســيارة جديــدة وأنهــم‬\n‫ا ومنحــوه ســيارة مســتعملة لالســتخدام املؤقــت بنــاء‬      ‫بــدأوا بالتنفيــذ فعـ ً‬\n‫علــى توجيهــات القاضــي وبســؤال املدعــي عــن ذلــك قــال‪ :‬نعــم هــذا‬\n‫ا عنــد القاضــي الشــيخ (‪ )....‬وبعــرض ذلــك علــى املدعــى‬           ‫حصــل فع ـ ً‬\n‫عليــه قــال‪ :‬أنــا لــم أكــن حاضــر ًا يف جميــع اجللســات وأطلــب رفــع جللســة‬\n‫للرجــوع وســؤال مــن كان حاضــر ًا يف اجللســة ورفعــت اجللســة لذلــك بعــد‬\n‫إعــام الطرفــن باحلضــور يــوم الثالثــاء املوافــق ‪1433/3/15‬ه ـ الســاعة‬\n‫العاشــرة‪ .‬وبــاهلل التوفيــق‪ .‬ويف جلســة أخــرى يــوم الثالثــاء املوافــق‬\n‫‪1433/3/15‬ه ـ افتتحــت اجللســة وفيهــا حضر الطرفان وبســؤال املدعى‬\n‫عليــه وكالــة عــن جوابــه عمــا ذكــره املدعــي مــن الصلــح قــال‪ :‬الــذي‬\n‫حصــل عنــد الشــيخ (‪ )....‬أننــا اصطلحنــا مــع املدعــي علــى إعطائه ســيارة‬\n‫موديــل (‪ )....‬وتســحب منــه الســيارة القدميــة ويدفــع الفــرق بــن املوديلــن‬\n‫ومت توفيــر ســيارة بديلــة للمدعــي إلــى حــن متــام الصلــح علــى أنــه إذا ثبــت‬\n‫ا مصنعيـ ًا يتــم إصــاح الســيارة عن طريــق املصنع وبعرض‬           ‫أن هنــاك خلـ ً‬\n‫ذلــك علــى املدعــي قــال‪ :‬نحــن اتفقنــا علــى أن يســلموا لــي ســيارة بديلــة‬\n\n\n                                                                                         ‫‪36‬‬\n\f     ‫بــدل لســيارتي التــي فيهــا اخللــل املصنعــي وأعطونــي ســيارة مؤقتــة حتــى‬\n     ‫ا اســتلمت الســيارة‬   ‫تنتهــي معاملتــي يف الشــركة كمــا قالــوا وفع ـ ً‬\n     ‫املؤقتــة وأثنــاء ســيري يف أحــد الشــوارع فوجئــت بالشــرطة يوقفوننــي‬\n     ‫وينزلــون أوالدي مــن الســيارة ويقولــون كلــم أحــد يأخــذ أوالدك‬\n     ‫وأودعونــي بالســجن وأمــا اخللــل املصنعــي فلــم يتعرضــوا لــه يف الصلــح‬\n     ‫وبســؤال املدعــي هــل لديــه بينــة علــى ذلــك قــال‪ :‬إن الشــيخ (‪ )....‬هــو‬\n     ‫الــذي كان حاضــر ًا معنــا وأطلــب مخاطبتــه بهــذا اخلصــوص ورفعــت‬\n     ‫اجللســة لذلك بعد إعالم الطرفني باحلضور يوم األربعاء ‪1433/3/30‬هـ‬\n     ‫الســاعة احلاديــة عشــرة وبــاهلل التوفيــق‪ .‬ويف جلســة أخــرى يــوم األربعــاء‬\n     ‫املوافــق‪ 1433/03/30‬ه ـ افتتحــت اجللســة وفيهــا حضــر الطرفــان وقــد‬\n     ‫جــرى مخاطبــة فضيلــة الشــيخ (‪ )....‬ولــم يردنــا منــه شــيء بهــذا اخلصوص‬\n     ‫لــذا جــرى رفــع اجللســة إلــى حــن ورود اخلطــاب بعــد إعــام الطرفــن‬\n     ‫باحلضــور يــوم األحــد ‪1433/4/11‬ه ـ الســاعة الثانيــة عســرة والنصــف‬\n     ‫وبــاهلل التوفيــق‪ .‬ويف جلســة أخــرى يــوم األحد‪1433/4/11‬ه ـ افتتحــت‬\n     ‫اجللســة وفيهــا حضــر الطرفــان ولــم يردنــي شــيء بخصــوص اخلطــاب‬\n     ‫املوجــه لفضيلــة الشــيخ (‪ )....‬وقــد أفــاد املدعــي بأنــه راجــع فضيلتــه‬\n     ‫وأفــاده أنــه بصــدد الــرد علــى اخلطــاب ورفعــت اجللســة حلــن وروده بعــد‬\n     ‫إعــام الطرفــن باحلضــور يــوم األربعــاء ‪1433/4/28‬ه ـ الســاعة احلاديــة‬\n     ‫عشــرة وبــاهلل التوفيــق‪ .‬ويف جلســة أخــرى يــوم األربعــاء املوافــق‬\n     ‫‪1433/04/28‬ه ـ افتتحــت اجللســة وفيهــا حضــر الطرفــان وقــد وردنــي‬\n     ‫خطــاب رئيــس محكمــة االســتئناف واملقيــد باحملكمــة رقــم‬\n     ‫‪ 33/698187‬وتاريــخ ‪1433/04/13‬ه ـ وبرفقــه خطــاب فضيلــة‬\n     ‫الشــيخ(‪ )....‬القاضــي مبحكمــة االســتئناف رقــم ‪ 33/561541‬وتاريــخ‬\n\n\n‫‪37‬‬\n\f‫‪1433/04/07‬ه ــواملتضمن مــا ملخصــه‪( :‬أفيدكــم بأنــه مضــى مــدة‬\n‫طويلــة علــى انتقالــي مــن املكتــب وال أذكــر تفاصيــل املوضــوع وإمنــا يف‬\n‫ذهنــي بعــض الشــيء مــن أنــه حــن عــودة املعاملــة مــن الكليــة التقنيــة‬\n‫حــدد لهــم موعــد ولــم يحضــر الوكيــل الشــرعي عــن شــركة (‪ )....‬وإمنــا‬\n‫حضــر منــدوب يعتــذر عــن عــدم حضــور الوكيــل لظــروف طارئــة‬\n‫فعرضــت عليــه أن ينقــل للوكيــل الشــرعي وأصحــاب الشــأن يف‬\n‫الشــركة بــأن يختصــروا علــى املدعــي طــول املداعــاة ويســلموا له ســيارة‬\n‫بديلــة واملدعــي يحضــر مــن األحســاء ملتابعــة الدعــوى هــذا مــا أذكــره يف‬\n‫شــأن مــا مت االستفســار عنــه) ا‪.‬هــ‪ .‬وعنــد وصــول القضيــة لهــذا احلــد مت‬\n‫رفعها للتأمل بعد إعالم الطرفني باحلضور يوم االثنني ‪1433/05/03‬هـ‬\n‫الســاعة العاشــرة والنصــف وبــاهلل التوفيــق‪ .‬ويف جلســة أخــرى يــوم‬\n‫االثنــن ‪1433/5/3‬ه ـ افتتحــت اجللســة وفيهــا حضــر الطرفــان وقــد‬\n‫جــرى دراســة املعاملــة فوجــدت علــى اللفــة رقــم (‪ )22‬اتفــاق بــن الطرفني‬\n‫مــدون علــى مســودة فــرع وزارة التجــارة باملنطقــة الشــرقية يتضمــن مــا‬\n‫ملخصــه‪ :‬أنــه يف يــوم األحــد املوافــق ‪1429/7/24‬ه ـ لقــد حضــر إلــى‬\n‫مقــر الــوزارة صاحــب الدعــوى (‪ )....‬ضــد شــركة (‪ )....‬للســيارات‬\n‫وحضــر الوكيــل الشــرعي للشــركة (‪ )....‬واملديــر الفنــي والضمــان‬\n‫للقطــاع واتفقــا الطرفــان علــى إحالــة الســيارة إلــى جهــة أخــرى كليــة‬\n‫التقنيــة بالدمــام لفحــص الســيارة‪ .‬انتهــى املقصــود منــه وموقــع مــن‬\n‫املدعــي ووكيــل الشــركة ومديــر (‪ )....‬كمــا وجــدت علــى اللفــة رقــم‬\n‫(‪56‬و‪ )57‬تقريــر الكليــة التقنيــة ويتضمــن مــا ملخصــه‪ :‬عليــه رأت‬\n‫اللجنــة بعــض النقــاط املهمــة التــي تؤخــذ بعــن االعتبــار من خــال معاينة‬\n‫الســيارة‪/1 :‬محــرك الســيارة كان مفكــوك ًا ومجــزأ يف مــكان آخــر‬\n\n\n                                                                                   ‫‪38‬‬\n\f     ‫مــن فتــرة طويلــة ممــا يصعــب علــى اللجنــة التقييــم الدقيــق للعطــل وذلــك‬\n     ‫لعــدم إمكانيــة تشــغيل احملــرك يف الوقــت احلالــي ليتــم اختبــاره‪/2 .‬‬\n     ‫ترســب الزيــت علــى األجــزاء الداخليــة للمحــرك قــد يكــون مــن طــول‬\n     ‫الفتــرة التــي تــرك فيهــا احملــرك مفكــوك‪ /3 .‬صاحــب الســيارة كان‬\n     ‫منتظم ـ ًا يف تغييــر الزيــت حســب الفواتيــر التــي اطلعــت عليهــا اللجنــة‪.‬‬\n     ‫‪ /4‬عينــة الزيــت التــي مت أخذهــا مــن محــرك الســيارة كانــت لزوجتهــا‬\n     ‫جيــدة‪ /5 .‬صاحــب الســيارة يشــكو مــن فتــرة مــن ظهــور صــوت غيــر‬\n     ‫طبيعــي باحملــرك حيــث راجــع الشــركة أكثــر مــن مــرة ولــم حتــل‬\n     ‫املشــكلة‪/6 .‬الســيارة مــا زالــت حتــت ضمــان الوكالــة‪ .‬وإشــارة إلــى‬\n     ‫كل تلك املؤشــرات التي مت اســتقصاؤها من صاحب الســيارة والفنيني‬\n     ‫الذيــن عاينــوا الســيارة أثنــاء دخولهــا ولكــون الســيارة مــا زالــت حتــت‬\n     ‫الضمــان تــرى اللجنــة بــأن العيــب كان يف التشــخيص مــن قبــل الوكالة‬\n     ‫لذلــك رأت اللجنــة أن تتحمــل الوكالــة جميــع مــا يترتــب علــى ذلــك‬\n     ‫حســب نظــام الضمــان املشــمول لديهــم ‪ .‬ا‪.‬هــ‪ .‬وموقــع مــن أعضــاء اللجنــة‬\n     ‫كل مــن املهنــدس (‪ )....‬واملهنــدس (‪ )....‬واملهنــدس (‪ )....‬وقــد جــرى‬\n     ‫عــرض الفواتيــر التــي قدمهــا املدعــي علــى املترجــم باحملكمــة (‪)....‬‬\n     ‫مصــري اجلنســية باإلقامــة رقــم (‪ )....‬الــذي يترجــم مــن العربيــة إلــى‬\n     ‫االجنليزيــة وبالعكــس لبيــان مــا تتضمنــه فأفــاد بــأن جميــع الفواتيــر‬\n     ‫تتضمــن أن املدعــي يقــوم بتغييــر الزيــت علم ـ ًا أن عــدد الفواتيــر عشــر‬\n     ‫وقــد جــرى إرفــاق صــور مصدقــة منهــا يف املعاملــة ولتقــوي جانــب املدعي‬\n     ‫بالتقريــر الــوارد مــن الكليــة التقنيــة املشــار إليــه بعاليــه وبالفواتيــر التــي‬\n     ‫قدمهــا وأفــاد املترجــم تضمنهــا جميعهــا لتغييــر الزيــت فقد قررت ســماع‬\n     ‫ميينــه معهــا وبعرضهــا عليــه اســتعد بهــا وحلــف قائــا واهلل العظيــم عالــم‬\n\n\n‫‪39‬‬\n\f‫الغيــب والشــهادة أننــي كنــت منتظمــا يف تغييــر زيــت الســيارة التــي‬\n‫اشــتريتها مــن شــركة(‪ )....‬موكلــة املدعــى عليــه محــل الدعــوى وأن‬\n‫ـاء علــى مــا‬\n            ‫الــذي بهــا عيــب مصنعــي واهلل العظيــم ‪ .‬هكــذا حلــف فبنـ ً‬\n‫تقــدم مــن الدعــوى واإلجابــة وإلقــرار وكيــل املدعــى عليهــا بصحــة مــا‬\n‫جــاء يف دعــوى املدعــي مــن شــرائه مــن الشــركة موكلتــه الســيارة التــي‬\n‫ذكــر بالقيمــة التــي ذكــر إال أنــه أنكــر أن يكــون بهــا خلــل مصنعــي‬\n‫وذكــر أن ســبب تعطــل الســيارة هــو عــدم التــزام املدعــي بتغييــر الزيــت‬\n‫يف مواعيــده وبنــاء علــى التقريــر الفنــي الصــادر مــن الكليــة التقنيــة‬\n‫املذكــور بعاليــه والتــي رضــي الطرفــان بإحالــة الســيارة لهــا لتشــخيص‬\n‫ســبب تعطلهــا كمــا هــو وارد بعاليــه ولتقــوي جانــب املدعــي بالفواتيــر‬\n‫التــي قدمهــا واملذكــورة بعاليــه وبتقريــر الكليــة التقنيــة املذكــور وألن‬\n‫اليمــن تشــرع يف حــق أقــوى املتداعيــن كمــا قــرره أهــل العلــم وألن‬\n‫املدعــي حلــف علــى صفــة مــا ذكــر بعاليــه وألن املدعــي قــدم الفواتيــر‬\n‫التــي تفيــد تغييــره للزيــت عشــر مــرات خــال ســنتني تقريبــا وهــي مــدة‬\n‫بقــاء الســيارة عنــده كمــا ذكــر الطرفــان وكل ذلــك يؤكــد أن ســبب‬\n‫تعطــل الســيارة هــو وجــود خلــل مصنعــي بهــا وليــس عــدم تغييــر الزيــت‬\n‫وقــد قــرر أهــل العلــم أن وجــود العيــب يف الســلعة موجــب لردهــا وفســخ‬\n‫العقــد إذا أراد املشــتري وألنــه يتعــذر إبــدال الســيارة مــن نفــس املوديــل‬\n‫املذكــور فليــس للمدعــي ســوى إرجــاع القيمــة فبنــاء علــى كل مــا تقــدم‬\n‫فقــد حكمــت بإلــزام موكلــة املدعــى عليــه بدفــع مائــة وثمانــن ألــف‬\n‫ريـ‪ 180000‬ــال للمدعــي وصرفــت النظــر عمــا يطالــب بــه زيــادة علــى‬\n‫ذلــك وبعــرض ذلــك علــى الطرفــن قــرر املدعــي القناعــة واملدعــى عليــه‬\n‫وكالــة عدمهــا فأفهمتــه أن عليــه التقــدم خــال عشــرة أيــام الســتالم‬\n\n\n                                                                                    ‫‪40‬‬\n\f     ‫نســخة مــن صــك احلكــم وتقــدمي الالئحــة االعتراضيــة عليهــا خــال‬\n     ‫ثالثــن يومــا مــن تاريــخ االســتالم يســقط بعدهــا حقــه يف االعتــراض‬\n     ‫ويكتســب احلكــم القطعيــة وبــاهلل التوفيــق وصلــى اهلل وســلم علــى‬\n             ‫نبينا محمد وعلى آله وصحبه أجمعني ‪ .‬حرر يف ‪1433/5/3‬هـ ‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد ففــي يــوم الثالثــاء املوافــق ‪1433/11/9‬ه ـ‬\n     ‫فتحــت اجللســة بنــاء علــى عــودة املعاملــة مــن محكمــة االســتئناف‬\n     ‫باملنطقــة الشــرقية برقــم ‪ 331273632‬وتاريــخ ‪1433/9/17‬ه ـ‬\n     ‫وبرفقهــا قــرار أصحــاب الفضيلــة املرفــق رقــم ‪ 33405884‬وتاريــخ‬\n     ‫‪1433/9/9‬ه ــاملتضمن مــا نصــه بعــد املقدمــة‪( :‬وبدراســة الصك وصورة‬\n     ‫ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة لوحــظ أن املدعــى عليهــا‬\n     ‫قــد ذكــرت يف الالئحــة االعتراضيــة أن بإمكانهــا إعــادة تركيــب‬\n     ‫املاكينــة حتــى تتمكــن اللجنــة املشــكلة لــدى الكليــة التقنيــة مــن‬\n     ‫حتديــد مــا إذا كان العيــب مصنعي ـ ًا أو كان بســبب ســوء اســتخدام‬\n     ‫املدعــي للســيارة فعلــى فضيلتــه مالحظــة ذلــك ورصــد مــا يجــد يف‬\n     ‫الضبــط وصورتــه وملخصــه بالصــك وســجله وإكمــال الــازم حســب‬\n     ‫التعليمــات) وعليــه أجيــب أصحــاب الفضيلــة بــأن مــا ذكرتــه الشــركة‬\n     ‫غيــر متصــور وال معقــول بــل هــو إلــى االســتحالة أقــرب منــه إلــى الوقــوع‬\n     ‫إذ كيــف ميكــن التوصــل إلــى معرفــة اخللــل مــع بقــاء املاكينــة هــذه‬\n     ‫املــدة الطويلــة خــارج الســيارة بــل وبــدون عمــل وعليــه فليــس لــدي ســوى‬\n     ‫مــا حكمــت بــه وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                 ‫آلــه وصحبــه وســلم‪ .‬حــرر يف ‪1433/11/9‬هــ‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد ففــي يــوم الســبت املوافق‪1434/02/02‬ه ـ‬\n     ‫ـاء علــى عــودة املعاملــة مــن محكمــة االســتئناف‬      ‫افتتحــت اجللســة بنـ ً‬\n\n‫‪41‬‬\n\f‫باملنطقــة الشــرقية برقــم ‪ 332019168‬يف ‪1434/01/18‬ه ـ وبرفقهــا‬\n‫قــرار أصحــاب الفضيلــة قضــاة الدائــرة احلقوقيــة األولــى يف ذات‬\n‫احملكمــة برقــم ‪ 344533‬وتاريــخ ‪1434/01/06‬ه ـ املتضمــن املصادقــة‬\n‫علــى احلكــم قضــاة االســتئناف وتواقيعهــم وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/2/2‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                ‫‪42‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"17250706-b6cd-5618-b1f0-019e3dec82ff","source_page_start":27,"source_page_end":42,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"6fea01430c7f4902b7ce0e0ab509c825afcf39a6bf5ce41b86684dd37349580a","normalized_text_hash":"c2a5c003194fd5a678c4d8c182bef054f23d29f344c76f78241c5e1c742bd4a3","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v1-p27-33252287"},{"id":"84a0c627-9e98-5ba4-8ab1-bc97a61f0ff6","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -شراء سيارة -املطالبة برد ثمن السيارة والتعويض للعيب - االستعانة بأهل اخلبرة -سلبية التقرير الفني للمدعي -صرف النظر عن الدعوى وإخاء سبيل املدعى عليه .","document_number":"3436935","case_number":"1535","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باملدينة املنورة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/13","year":"1434","subject":"بيع -شراء سيارة -املطالبة برد ثمن السيارة والتعويض للعيب - االستعانة بأهل اخلبرة -سلبية التقرير الفني للمدعي -صرف النظر عن الدعوى وإخاء سبيل املدعى عليه .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫تاريخه‪1434/2/13:‬هـ‬\n                       ‫ُ‬               ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪3436935:‬‬\n                             ‫َر ْق ُم الدعوى‪1535 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34263572‬تاريخه‪1434/7/10 :‬هـ‬\n\n\n     ‫بيــع ‪ -‬شــراء ســيارة ‪ -‬املطالبــة بــرد ثمــن الســيارة والتعويــض للعيــب ‪-‬‬\n     ‫االســتعانة بأهــل اخلبــرة ‪ -‬ســلبية التقريــر الفنــي للمدعــي ‪ -‬صــرف‬\n                      ‫النظــر عــن الدعــوى وإخــاء ســبيل املدعــى عليــه ‪.‬‬\n\n\n\n\n                       ‫ما ذكره القاضي من مبادئ وقواعد يف تسبيب حكمه ‪.‬‬\n\n\n\n\n     ‫ادعــى املدعــي بأنــه اشــترى ســيارة وبعــد اســتالمها اكتشــف بهــا‬\n     ‫عيوب ـاً‪ ،‬قــام بإعــادة الســيارة إلــى البائــع ‪ ،‬طلــب املدعــي إعــادة ثمــن‬\n     ‫الســيارة والتعويــض عــن مــدة حرمانــه مــن الســيارة‪ ،‬صــادق املدعــى‬\n     ‫عليــه علــى دعــوى املدعــي لكــن مــا يتعلــق بالعيــوب ذكــر أنهــا موجــودة‬\n     ‫يف جميــع الســيارات مــن نفــس نوعهــا‪ ،‬متــت االســتعانة بأهــل اخلبــرة وقــد‬\n     ‫انتهــوا إلــى عــدم وجــود مشــكلة يف الســيارة‪ ،‬لــذا حكمــت احملكمــة‬\n     ‫بصــرف النظــر عــن دعــوى املدعــي وإخــاء ســبيل املدعــى عليــه ‪-‬‬\n                                  ‫مصادقــة محكمــة االســتئناف علــى احلكــم ‪.‬‬\n\n\n\n\n‫‪43‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...........‬القاضــي يف احملكمــة العامــة‬\n‫باملدينــة املنــورة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة باملدينــة املنــورة برقــم ‪ 1535‬وتاريــخ ‪ 1432/01/27‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 325836‬وتاريــخ ‪1432/01/27‬ه ـ افتتحــت‬\n‫اجللســة وفيهــا حضــر املدعــي ‪ ...........‬ســعودي اجلنســية مبوجــب الســجل‬\n‫املدنــي رقــم ‪ .........‬بالوكالــة عــن ‪ ..........‬مبوجــب الوكالــة الصــادرة‬\n‫مــن كتابــة العــدل الثانيــة بجنــوب جــدة برقــم ‪ 29083‬يف ‪1433/7/6‬ه ـ‬\n‫وادعــى علــى احلاضــر معــه ‪ ..........‬مبوجــب الســجل املدنــي رقــم ‪............‬‬\n‫بالوكالــة عــن ‪ ............‬بصفتــه املفــوض عــن شــركة ‪ ..........‬مبوجــب‬\n‫الفقــرة الرابعــة مــن املــادة الثانيــة عشــرة مــن عقــد التأســيس املعــدل‬\n‫للشــركة واملثبــت بالســجل التجــاري رقــم ‪ ..................‬صــادر مــن‬\n‫الريــاض يف ‪1407/3/8‬ه ـ مبوجــب الوكالــة الصــادرة مــن كتابــة عدل‬\n‫ا يف دعــواه عليــه إننــي‬   ‫املدينــة برقــم ‪ ....‬وتاريــخ ‪1431/3/14‬ه ـ قائ ـ ً‬\n‫اشــتريت مــن شــركة ‪ ...........‬ســيارة نــوع ‪ ) ...........( .......‬انتــاج ‪2010‬م‬\n‫مببلــغ مائــة وثمانيــة وثالثــن ألفـ ًا وأربعمائــة ريــال وكان ذلــك يف شــهر‬\n‫رجــب أو شــعبان مــن عــام ‪1431‬ه ـ وبعــد اســتالمي للســيارة تبــن لــي أن‬\n‫فتحــة املكيــف الســفلية ال تقفــل بشــكل تــام ممــا يتســبب لــي بأضــرار‬\n‫يف قدمــي كمــا أنــه حصــل عطــل يف جهــاز نقــل احلركــة ( اجليربكــس‬\n‫) تكــرر وقوعــه ولتضــرري مــن ذلــك أعــدت الســيارة إليهــم منــذ حوالــي‬\n‫ثالثــة أشــهر ورفضــت اســتالمها وأطلــب إعــادة املبلــغ الــذي ســلمته لهــم‬\n‫وتعويضــي عــن املــدة التــي حرمــت فيهــا مــن ســيارتي وثمنهــا هــذه دعــواي‬\n\n                                                                                      ‫‪44‬‬\n\f     ‫وبعــرض ذلــك علــى املدعــى عليــه قــال مــا ذكــره املدعــي مــن شــرائه‬\n     ‫الســيارة املذكــورة باملبلــغ املذكــور مــن شــركة ‪ .........‬ومــا ذكــره عــن‬\n     ‫التكييــف واجليربكــس صحيــح لكــن مــا يتعلق بالتكييــف ليس عيب ًا‬\n     ‫يف الصناعــة بــل ميــزة يف الســيارة موجــودة يف جميــع الســيارات التــي هي‬\n     ‫مــن نــوع ســيارته وقــد خوطــب املصنــع بذلــك ملعاجلتــه وأمــا اجليربكــس‬\n     ‫فإنــه لــم يكــن فيــه خلــل مصنعــي بــل هــو مبرمــج علــى ســرعة الســيارة‬\n     ‫فــإذا جتاوزهــا يحتــاج إلــى إعــادة برمجــة والســيارة اآلن ليــس فيهــا عيــب‬\n     ‫وجاهــزة ميكــن للمدعــي اســتالمها ثــم قــال املدعــي بأننــي خاطبــت‬\n     ‫هيئــة املواصفــات واملقاييــس فذكــروا لــي بــأن هــذا العيــب لــم يــدرج يف‬\n     ‫مقاييــس الســيارات الســعودية ولــذا ال تعتبــر يف الوقــت احلاضــر مخالفــة‬\n     ‫ال كمــا أنــي راجعت قســم الغش‬     ‫للمقاييــس ولكــن ســوف تــدرج مســتقب ً‬\n     ‫التجــاري بــوزارة التجــارة فطلبــوا تقريــر ًا مــن الشــركة املدعــى عليهــا‬\n     ‫مــن أجــل مخاطبــة املعهــد الصناعــي باملدينــة فقدمــت الشــركة لهــم بــأن‬\n     ‫مــا أدعيــه ال يعتبــر عيبـ ًا وطلبــت منــي وزارة التجــارة التوقيــع علــى ذلــك‬\n     ‫فلــم أوافــق ألن جــواب املعهــد ســيكون وفــق مــا ذكرتــه الشــركة ثــم‬\n     ‫أفهمــت املدعــى عليــه وكالــة بــأن عليــه إحضــار تقريــر فنــي مفصل يبني‬\n     ‫وجهــة نظــر مصنــع الســيارة يف ســبب صناعــة املكيــف واجليربكــس‬\n     ‫علــى الصفــة املذكــورة ومبــررات ذلــك بصــورة واضحــة علــى أن يكــون‬\n     ‫التقريــر باللغتــن العربيــة واالجنليزيــة مــع التأكــد من مطابقــة الترجمة‬\n     ‫لعرضــه علــى أهــل اخلبــرة ثــم أبــرز املدعــى عليــه وكالــة إفــادة مدونــه‬\n     ‫باللغــة االجنليزيــة علــى مطبوعــات شــركة ‪ ...........‬مؤرخــة يف ‪/22‬‬\n     ‫مــارس‪2011/‬م يوافــق ‪1432/4/17‬ه ـ وبرفقهــا ترجمــة مــن مكتــب‬\n     ‫‪ .............‬للترجمــة مؤرخــة يف ‪1432/4/21‬ه ـ ونصــه نحيطكــم علم ـ ًا‬\n\n\n‫‪45‬‬\n\f‫بــأن منتجــات شــركة ‪ ..............‬للســيارات التــي يتــم صنعهــا يف أمريكا‬\n‫الشــمالية وتبــاع يف اململكــة العربيــة الســعودية تتمتــع بضمــان كامــل‬\n‫مــن الصانــع ملــدة ( ‪ )3‬ســنوات أو ‪ 60000‬ألــف كيلــو متــر أيهمــا ينقضــي‬\n‫أو ًال باإلضافــة لذلــك تقــدم شــركة ‪ ......‬للســيارات ضمانـ ًا على منظومة‬\n‫الدفــع للســيارات التــي صنعــت يف أمريــكا الشــمالية ملــدة ( ‪ )5‬ســنوات‬\n‫أو ‪ 100000‬ألــف كيلــو متــر أيهمــا ينقضــي وكال الضمانــن يبــدآن‬\n‫مــن تاريــخ بيــع الســيارة للعميــل وينتهيــان يف أي األجلــن يكــون أو ًال ‪.‬‬\n‫بخصــوص املوضــوع اخلــاص مبالــك الســيارة فــورد إكسبيدشــن برقــم‬\n‫الهيــكل ‪ ...........:‬مت التعامــل مــع هــذا األمــر بواســطة وكيــل شــركة‬\n‫‪ ......‬للســيارات املعتمــد‪ ......... /‬ضمــن حــدود ضمــان املصنــع وبخصــوص‬\n‫توزيــع هــواء التكييــف داخــل الســيارة فهــذا أمــر عــادي يف هــذه الســيارة‬\n‫والنظــام يعمــل جيــد ًا وفــق معاييــر التصميــم ‪ .‬يف حالــة مالحظــة العميــل‬\n‫مســتقبال حــدوث أي منغصــات يف هــذه الســيارة ســتقوم شــركة فــورد‬\n‫للســيارات بتقــدمي أي مســاعدة مــن خــال الضمــان اخلــاص بالســيارة‪.‬‬\n‫( عــن ‪ ......‬الشــرق األوســط (توقيــع) املديــر اإلقليمــي قســم املبيعــات‬\n‫شــركة ‪ . ) ........‬أ ‪ .‬ه ـ وحيــث أن اإلفــادة غيــر مالقيــة للمطلــوب وجاءت‬\n‫متأخــرة كثيــر ًا ســألت املدعــى عليــه وكالــة هــل تصميــم توزيــع الهــواء‬\n‫موجــود يف بقيــة ســيارات ‪ ........‬مثــل الســيارة موضــع الدعوى وكم أنواع‬\n‫ســيارات ‪ ..........‬فقــال ال أعلــم وسأســال موكلتــي شــركة توكيــات‬\n‫‪ . ...........‬ثــم قــررت الكتابــة لقســم اخلبــراء لعــرض الســيارة علــى أهــل‬\n‫اخلبــرة بحضــور الطرفــن وســؤالهم عــن موضــع الدعــوى وهــل يعتبر عيب ًا‬\n‫وفيــه ضــرر وهــل يعلمــون وجــوده يف غيرهــا مــن الســيارات من شــركات‬\n‫أخــرى باعتبــاره ميــزة فيهــا واإلفــادة عــن ذلــك بدقــة ثــم متــت الكتابــة‬\n\n\n                                                                                    ‫‪46‬‬\n\f     ‫للمؤسســة العامــة للتدريــب التقنــي واملهنــي املعهــد الصناعــي الثانــوي‬\n     ‫الثانــي باملدينــة املنــورة فوردنــا خطابهــم رقــم ‪ 146028/301/2/19‬يف‬\n     ‫‪1433/7/13‬ه ـ ونــص احلاجــة منــه ‪ :‬بشــأن الكشــف علــى الســيارة مــن‬\n     ‫نــوع ‪ )...........( ..........‬إنتــاج ‪2010‬م حيــال املالحظــات التــي ذكــرت يف‬\n     ‫خطــاب فضيلتكــم عليــه نفيــد فضيلتكــم أنــه بعــد الكشــف علــى‬\n     ‫الســيارة املذكــورة بحالتهــا عنــد إحضارهــا للمعهــد ومباشــرة جلنــة‬\n     ‫الفحــص ملعاينتهــا وجتربتهــا اتضــح اآلتــي ‪ -1 :‬عــدم وجــود املشــكلة‬\n     ‫يف اجليربكــس وقــت فحــص وجتربــة الســيارة التــي ذكــرت يف خطــاب‬\n     ‫فضيلتكــم ‪ -2 .‬مت الكشــف علــى الســيارة بخصــوص التكييــف‬\n     ‫وكذلــك علــى ســيارات مماثلــة نفــس النــوع واملوديــل وموديــات مختلفــة‬\n     ‫تبــن أن املالحظــة موجــودة يف الســيارة والســيارات التــي مت الكشــف‬\n     ‫عليهــا ‪ .‬انتهــى ‪ .‬فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وملــا قــرره‬\n     ‫أهــل اخلبــرة يف القــرار املثبــت نصــه مــن عــدم وجــود املشــكلة يف اجليــر‬\n     ‫بكــس وقــت فحــص وجتربــة الســيارة وأن مــا كان يف تكييــف‬\n     ‫الســيارة محــل النــزاع موجــود يف كل الســيارات املماثلــة فقــد صرفــت‬\n     ‫النظــر عــن دعــوى املدعــي وأخليــت ســبيل املدعــى عليــه هــذا مــا ظهــر‬\n     ‫لــي وبــه حكمــت وبعرضــه علــى الطرفــن قــرر املدعــي وكالــة عــدم‬\n     ‫القناعــة وأفهمتــه بتعليمــات التمييــز ففهــم ثــم جــرى تســليمه نســخة مــن‬\n     ‫صــك احلكــم وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد برفــع احلكــم إلــى محكمــة االســتئناف مبنطقــة‬\n     ‫مكــة املكرمــة عــادت األوراق برفقهــا قــرار الدائــرة احلقوقيــة الثالثــة‬\n     ‫رقــم ‪ 34210512‬يف ‪1434/5/11‬ه ـ ويتضمــن املالحظــة باألكثريــة‬\n     ‫علــى احلكــم ونــص احلاجــة منــه وبدراســة احلكــم وصــورة ضبطــه‬\n\n\n‫‪47‬‬\n\f‫والئحتــه االعتراضيــة تقــرر باألكثريــة إعادتهــا لفضيلتــه فقــد ذكــر‬\n‫املدعــى عليــه يف الالئحــة بــأن (اجليربكــس) فيــه برمجــة ‪ ..‬إلــخ ولــم‬\n‫يقــم فضيلتــه مبناقشــة املوضــوع وهــل هــذا فيــه عيــب أو هــو أمــر طبيعــي‬\n‫فالبــد مــن مناقشــة األمــر مــع أهــل اخلبــرة ‪ ،‬وتعطيــل الســيارة تلــك املــدة‬\n‫أال يســتحق املدعي تعويض ًا إذا كان التعطيل بســبب الشــركة ‪ .‬وباهلل‬\n‫التوفيــق ‪ ،‬وجواب ـ ًا عليــه فــإن املعهــد الصناعــي الثانــوي الثانــي باملدينــة‬\n‫أفــاد إنــه بعــد الكشــف علــى الســيارة مــن جلنــة الفحــص ومعاينتهــا‬\n‫وبتجربتهــا اتضــح عــدم وجــود املشــكلة يف اجليربكــس وقــت فحــص‬\n‫الســيارة ‪ ،‬ومــادام أن املعهــد الصناعــي أفــاد بذلــك وهــو صاحــب اخلبــرة‬\n‫والفصــل يف هــذه األمــور فــإن مناقشــتها بعــد ذلــك ال وجــه لــه ‪ ،‬لــذا‬\n‫لــم يظهــر لــي ســوى مــا أجريتــه وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا‬\n             ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/06/19‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد برفــع احلكــم إلــى محكمــة االســتئناف مبكــة‬\n‫املكرمــة عــاد مصادق ـ ًا عليــه مبوجــب قــرار الدائــرة احلقوقيــة الثالثــة‬\n‫برقــم ‪ 34263572‬وتاريــخ ‪1434/7/10‬ه ـ ونــص احلاجــة منــه (وبدراســة‬\n‫احلكــم وصــورة ضبطــه والئحتــه االعتراضيــة تقــررت املوافقــة علــى‬\n‫احلكــم بعــد اإلجــراء األخيــر) وقــد ذيــل بتوقيعــات قضــاة االســتئناف ‪،‬‬\n‫‪.........‬و‪.............‬و‪ .........‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                ‫وســلم حــرر يف ‪1434/9/9‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                          ‫‪48‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"17250706-b6cd-5618-b1f0-019e3dec82ff","source_page_start":43,"source_page_end":48,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"3c343393e713fc19b9d74cb365166d5197ab03ba2469e2b082d5cc23265f7c1a","normalized_text_hash":"58aa88e9632917c42b7ce5fee08afa5f0780d761f3caa78503b0cbd296846a93","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v1-p43-3436935"},{"id":"f4fceb46-d778-5709-a0a1-4458f345cff7","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -توريد أجهزة طبية دون قبض الثمن -مطالبة بسداد الثمن- بينة املدعي -مصادقة املدعى عليه على جزء من املبلغ وإنكار الباقي -مطالبة املدعي الفصل يف القضية بحالتها -احلكم بجزء من الثمن وصرف النظر عن باقي الثمن .","document_number":"33296287","case_number":"2163","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بعنيزة","circuit":"الدائرة املختصة بتدقيق القضايا احلقوقية مبحكمة الاستئناف","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/6/14","year":"1434","subject":"بيع -توريد أجهزة طبية دون قبض الثمن -مطالبة بسداد الثمن- بينة املدعي -مصادقة املدعى عليه على جزء من املبلغ وإنكار الباقي -مطالبة املدعي الفصل يف القضية بحالتها -احلكم بجزء من الثمن وصرف النظر عن باقي الثمن .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1433/6/14 :‬هـ‬\n                      ‫ُ‬                ‫َر ْق ُم َّ‬\n                         ‫الص ِّك‪33296287 :‬‬\n                            ‫َر ْق ُم الدعوى‪2163 :‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                 ‫‪ 3463820‬تاريخه‪1434/3/16 :‬هـ‬\n\n\n     ‫بيــع‪ -‬توريــد أجهــزة طبيــة دون قبــض الثمــن‪ -‬مطالبــة بســداد الثمــن‪-‬‬\n     ‫بينــة املدعــي‪ -‬مصادقــة املدعــى عليــه علــى جــزء مــن املبلــغ وإنــكار‬\n     ‫الباقــي‪ -‬مطالبــة املدعــي الفصــل يف القضيــة بحالتهــا ‪ -‬احلكــم بجــزء‬\n                                 ‫مــن الثمــن وصــرف النظــر عــن باقــي الثمــن ‪.‬‬\n\n\n\n\n                       ‫ما ذكره القاضي من مبادئ وقواعد يف تسبيب حكمه ‪.‬‬\n\n\n\n\n     ‫ادعــى املدعــي بــأن املؤسســة موكلتــه قامــت بتوريــد أجهــزة طبيــة‬\n     ‫للشــركة املدعــى عليهــا لتركيبهــا يف مســتوصف‪ ،‬لــم تقــم الشــركة‬\n     ‫املدعــى عليهــا بســداد قيمــة هــذه األجهزة‪ ،‬طلب املدعي إلزام الشــركة‬\n     ‫ا علــى ذلــك كشــف حســاب يؤكــد هــذه‬             ‫بســداد القيمــة وقــدم دلي ـ ً‬\n     ‫املديونيــة‪ ،‬صــادق املدعــى عليــه وكالــة علــى دعــوى املدعــي إال أنــه أبــرز‬\n     ‫أن عدم ســداد الشــركة للمبلغ كان بســبب تأخر املؤسســة املدعية يف‬\n     ‫تركيــب األجهــزة ووجــود عطــل يف بعــض هــذه األجهــزة‪ ،‬طلــب املدعــي‬\n     ‫وكالــة ســرعة البــت يف القضيــة ‪ ،‬نظــر ًا ألن املدعــي وكالــة قــد طلــب‬\n     ‫ســرعة البــت يف الدعــوى بحكــم قبــل تقــدمي األدلــة الدالــة علــى مديونيــة‬\n     ‫الشــركة املدعــى عليهــا بكامــل املبلــغ‪ ،‬لــذا حكمت احملكمــة بإلزام‬\n\n‫‪49‬‬\n\f‫الشــركة املدعــى عليهــا بدفــع جــزء مــن الثمــن وصــرف النظــر عــن باقــي‬\n‫الثمــن‪ ،‬مت إفهــام املدعــي وكالــة بأحقيتــه يف إقامــة دعــوى مســتقلة‬\n‫للمطالبــة باملبلــغ الــذي صرفــت احملكمــة النظــر عنــه حــال رغبتــه يف‬\n                    ‫ذلــك‪ ،‬مصادقــة محكمــة االســتئناف علــى احلكــم ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد ويف يــوم الســبت املوافــق ‪1433/1/15‬ه ـ افتتحــت‬\n‫اجللســة يف الســاعة احلاديــة عشــر صباحــا لــدي أنــا ‪...................‬القاضــي‬\n‫باحملكمــة العامــة بعنيــزة للنظــر يف الدعــوى املقدمــة مــن مؤسســة‬\n‫‪ ...........‬ضــد شــركة ‪ ...........‬الطبيــة والتــي ســبق أن صــدر فيهــا قرارنــا‬\n‫بعــدم االختصــاص رقــم ‪8/70‬ض يف ‪1431/7/29‬ه ـ املصــدق مــن‬\n‫الدائــرة املختصــة بتدقيــق القضايــا احلقوقيــة مبحكمــة االســتئناف‬\n‫مبنطقــة القصيــم بقرارهــا رقــم ‪/125‬ق‪/‬أ يف ‪1431/10/25‬ه ـ وقــد‬\n‫وردنــا خطــاب معالــي رئيــس املجلــس األعلــى للقضــاء رقــم ‪ 11405‬يف‬\n‫‪1432/7/10‬ه ـ املتضمــن أنــه بإحالــة هــذه القضيــة إلــى جلنــة الفصــل يف‬\n‫تنــازع االختصــاص صــدر بشــأنها القــرار رقــم ‪/71‬ت يف ‪1432/7/4‬ه ـ‬\n‫ثــم جــرى االطــاع علــى هــذا القرار فوجدتــه يتضمــن أن اللجنة املختصة‬\n‫قــد اطلعــت علــى قرارنــا رقــم ‪8/70‬ض يف ‪1431/7/29‬ه ـ وقــرار‬\n‫ديــوان املظالــم رقــم ‪/96‬د‪/‬جت‪ 33/‬لعــام ‪1431‬ه ـ وهمــا يقضيــان بعــدم‬\n‫االختصــاص وقــررت اللجنــة أن القضيــة مــن اختصــاص القضــاء العــام أ‪.‬‬\n‫هـ ‪ .‬وقد حضر يف هذه اجللسة ‪ ..................‬سعودي مبوجب السجل رقم‬\n‫‪ ................‬الوكيــل عــن ‪ ..................‬ســعودي مبوجــب الســجل املدنــي‬\n\n                                                                                       ‫‪50‬‬\n\f     ‫رقــم ‪ ................‬الــذي وكلــه بصفتــه صاحــب ‪ .............‬ذات الســجل‬\n     ‫التجــاري رقــم ‪ ................‬يف ‪1426/5/4‬ه ـ الصــادر مــن جــده وبصفتــه‬\n     ‫صاحــب مؤسســة ‪ .....................‬ذات الســجل التجــاري رقــم ‪...................‬‬\n     ‫يف ‪1426/7/3‬ه ـ الصــادر مــن الريــاض وبصفــه صاحــب مؤسســة‬\n     ‫‪ ..................‬ذات الســجل التجــاري رقــم ‪ ..............‬يف ‪1426/7/10‬ه ـ‬\n     ‫الصــادر مــن الدمــام وذلــك مبوجــب الوكالــة الصــادرة مــن كاتــب عــدل‬\n     ‫اخلطــوط الســعودية املكلــف رقــم ‪ 20‬يف ‪1431/4/4‬ه ـ جلــد (‪/9‬س)‬\n     ‫وادعــى علــى ‪ .........................‬ســعودي بالســجل رقــم ‪............................‬‬\n     ‫الوكيــل عــن ‪ ..................‬ســعودي بالســجل رقــم ‪ ................‬الــذي‬\n     ‫وكلــه بصفتــه وكيــا عــن ‪ ............................‬بالوكالــة رقــم ‪830‬‬\n     ‫جلــد ‪ 730‬يف ‪1430/4/8‬ه ـ الصــادرة مــن كاتــب عــدل حوطــة ســدير‬\n     ‫والــذي وكلــه بصفتــه مديــر ‪ .......................‬املقيــدة بالســجل التجــاري‬\n     ‫الصــادر مــن الريــاض وذلــك مبوجــب الوكالــة الصــادرة مــن كاتــب‬\n     ‫عــدل عنيــزة برقــم ‪ ....................‬يف ‪1432/3/11‬ه ـ قائــا يف حتريــر‬\n     ‫دعــواه علــى الشــركة لقــد قامــت املؤسســة موكلتــي بتوريــد عــدد مــن‬\n     ‫األجهــزة الطبيــة لشــركة ‪ ...............‬الطبيــة لتركيبهــا يف مســتوصف‬\n     ‫‪ ................‬الطبــي بعنيــزة وقــد اجتمــع علــى الشــركة مســتحقات ماليــة‬\n     ‫قدرهــا أربعمائــة وخمســة آالف وتســعمائة وخمســون ريــاال أطلــب إلــزام‬\n     ‫شــركة ‪ ................‬الطبيــة بدفــع هــذه املســتحقات للمؤسســة موكلتــي‬\n     ‫هــذه دعــواي وبســؤال املدعــى عليــه وكالــة عمــا جــاء يف دعــوى املدعــي‬\n     ‫وكالــة أجــاب قائــا أطلــب إمهالــي لتدقيــق املســتندات املقدمــة مــن‬\n     ‫الشــركة املدعيــة وهــي كشــف احلســاب املقــدم مــن مؤسســة ‪..............‬‬\n     ‫إلــى شــركة ‪ ...........‬الطبيــة وإقــرار الشــركة باملديونيــة وتصديقهــا‬\n\n\n‫‪51‬‬\n\f‫علــى كشــف احلســاب آنــف الذكــر وذلــك حتــى تكــون إجابتــي‬\n‫واضحــة هكــذا أجــاب ثــم أمهــل لذلــك وقــرر اســتالمه صــورا مــن هــذه‬\n‫املســتندات وعددهــا ورقتــان ثــم رفعــت اجللســة ويف يــوم الثالثــاء املوافــق‬\n‫‪1433/3/22‬ه ـ افتتحــت اجللســة يف الســاعة التاســعة والنصــف صباحـ ًا‬\n‫وقــد جــرى التنويــه إلــى أن جلســة االثنــن املوافــق ‪1433/2/22‬ه ـ لــم‬\n‫يضبــط فيهــا شــيئ نظــر ًا لتمتعنــا بإجــازة عاديــة وقــد حضــر يف هــذه‬\n‫اجللســة املدعــي وكالــة ‪.............‬ولــم يحضــر املدعــى عليــه أصالــة وال‬\n‫وكيلــه الشــرعي ونظــر ًا ألن املدعــى عليــه أصالــة لــم يحضــر وكــذا لــم‬\n‫يحضــر وكيلــه الشــرعي فقــد قــررت ســماع بينة املدعي أصالة وبســؤال‬\n‫املدعــي وكالــة ألديــك بينــة علــى مــا جــاء يف دعــواك فقــال نعــم ثــم أبــرز‬\n‫أصل كشــف حســاب صادر من ‪ ..................‬ذات الســجل التجاري رقم‬\n‫(‪ ).....................‬محــرر ًا علــى مطبوعــات املؤسســة الرســمية وهــو موجــه‬\n‫إلــى شــركة ‪ ...............‬الطبيــة وقــد جــاء فيــه أن املديونيــة املســتحقة‬\n‫علــى شــركة ‪ ................‬الطبيــة حتــى تاريــخ ‪ 2010/5/1‬هــو مبلــغ قــدره‬\n‫أربعمائــة وخمســة آالف وتســعمائة وخمســون ريــا ًال وقــد وقــع عليــه مــن‬\n‫شــخص يدعــى ‪ .................‬يف (‪ )2010/5/4‬ودون فيــه عبــارة نصهــا‬\n‫أن الرصيــد مطابــق حســب دفاترنــا ومختــوم بختــم إدارة احملاســبة يف‬\n                                                      ‫شــركة ‪ .............‬الطبيــة ‪.‬‬\n‫كمــا أبــرز أصــل كشــف حســاب مماثــل لــأول متام ـ ًا وقــد جــاء‬\n‫فيــه أن املديونيــة املســتحقة علــى شــركة ‪........‬الطبيــة حتــى تاريــخ‬\n‫‪2011/12/10‬م هــو مبلــغ قــدره أربعمائــة وخمســة آالف وتســعمائة‬\n‫وخمســون ريــا ًال وعليــه نفــس التوقيــع والعبــارة واخلتــم أ‪.‬هــ‪ .‬ثــم رفعــت‬\n‫اجللســة ويف يوم األحد املوافق ‪1433/5/2‬هـ افتتحت اجللســة يف الســاعة‬\n\n\n                                                                                        ‫‪52‬‬\n\f     ‫التاســعة والنصــف صباح ـ ًا وفيهــا حضــر املدعــي وكالــة ‪................‬‬\n     ‫ا لقــد ســبق‬    ‫واملدعــى عليــه وكالــة ‪ ..........‬ثــم قــرر املدعــي وكالــة قائـ ً‬\n     ‫أن قدمــت بيناتــي يف اجللســة الســابقة وإننــي اكتفــي بهــا وأطلــب احلكم‬\n     ‫مبوجبهــا هكــذا قــرر ونظــر ًا الن املدعــى عليــه وكالــة قــد حضــر يف‬\n     ‫هــذه اجللســة وقــد ســبق ســماع بينــات املدعــي أصالــة نظــر ًا لعــدم حضــور‬\n     ‫املدعــى عليــه أصالــة وال مــن ينــوب عنــه لــذا فقــد ســألت املدعــى عليــه‬\n     ‫ا أمــا الدعــوى‬      ‫وكالــة اجلــواب عــن الدعــوى والبينــات فأجــاب قائ ـ ً‬\n     ‫فصحيــح أن الشــركة املدعيــة قامــت بتوريــد عــدد مــن األجهــزة الطبيــة‬\n     ‫لشــركة ‪ .........‬الطبيــة وقامــت بتركيبهــا كاملــة مببلــغ إجمالــي قــدره‬\n     ‫أربعمائــة وخمســة آالف وتســعمائة وخمســون ريــا ًال ولــم تســدد الشــركة‬\n     ‫موكلتــي مــن هــذا املبلــغ أي شــيئ حتــى تاريخــه لكن هذا كان بســبب‬\n     ‫أن الشــركة املدعيــة تأخــرت يف تركيــب بعــض هــذه األجهــزة كمــا‬\n     ‫أن مــن ضمــن هــذه األجهــزة جهــاز طبــي مبلحقاتــه قــدرت قيمتــه مببلــغ‬\n     ‫قــدره مائــة وتســعون ألــف ريــال تقريبـ ًا قامــت الشــركة املدعيــة بتوريــده‬\n     ‫ضمــن هــذه األجهــزة وتبــن أنــه متعطــل عــن العمــل وقامــت الشــركة‬\n     ‫موكلتــي بإبــاغ املهنــدس ‪ ..............‬الــذي يعمــل يف الشــركة املدعيــة‬\n     ‫وهــو املســئول عــن تركيــب هــذه األجهــزة فوعــد مبراجعــة الشــركة‬\n     ‫موكلتــي لصيانتــه وإصالحــه وتقديــر حجــم العطــل املوجــود فيــه‬\n     ‫ولكنــه لــم يراجــع الشــركة موكلتــي حتــى اآلن ولــذا فإننــي أطلــب‬\n     ‫خصــم قيمــة إصــاح هــذا اجلهــاز بعــد تقديــر ذلــك مــن جهــة مختصــة مــن‬\n     ‫املبلــغ املدعــى بــه كــي تلتــزم الشــركة موكلتــي بدفــع املبلــغ املتبقــي‬\n     ‫هــذا جوابــي علــى الدعــوى وأمــا جوابــي علــى البينــات املقدمــة مــن‬\n     ‫الشــركة املدعيــة فــان الشــركة موكلتــي لــم تعــارض علــى قيمــة هــذه‬\n\n\n‫‪53‬‬\n\f‫األجهــزة بــل إن قيمتهــا صحيحــة وهــي كامــل املبلــغ املدعــى بــه ولكــن‬\n‫معارضــة الشــركة موكلتــي تتعلــق بذلــك اجلهــاز املتعطــل املذكــور‬\n‫ا‬‫آنف ـ ًا هكــذا أجــاب وبعــرض ذلــك علــى املدعــي وكالــة أجــاب قائ ـ ً‬\n‫إننــي أطلــب إمهالــي إلحضــار ردي محــرر ًا يف اجللســة القادمــة فأجيــب‬\n                                                      ‫لذلــك ثــم رفعــت اجللســة ‪.‬‬\n‫ويف يــوم الســبت املوافــق ‪1433/6/14‬ه ـ افتتحــت اجللســة يف الســاعة‬\n‫التاســعة والنصــف صباحــا وفيهــا حضــر املدعــي وكالــة ‪...............‬‬\n‫واملدعــى عليــه ‪ .........‬ثــم أبــرز املدعــي وكالــة رده علــى مــا جــاء يف‬\n‫جــواب املدعــى عليــه وكالــة يف اجللســة الســابقة واملكــون مــن صفحتني‬\n‫مت ضمهــا باملعاملــة ثــم قــرر قائــا إن ملخــص ردي هــو أن مــا ذكــره‬\n‫املدعــى عليــه وكالــة يف جوابــه مــن وجــود جهــاز متعطــل فهــذا غيــر‬\n‫صحيــح نظــرا ألنــه ال يوجــد أي جهــاز مــن األجهــزة املباعــة قيمتــه‬\n‫مائــة وتســعون ألــف ريــال كمــا أن جميــع تلــك األجهــزة مت تركيبهــا‬\n‫وتشــغيلها وتســليمها للشــركة مــع شــهادة ضمــان ســنه للتشــغيل ولــم‬\n‫يصــل لشــركة موكلــي أي طلــب رســمي مــن الشــركة املدعــى عليهــا‬\n‫بوجــود جهــاز متعطــل خــال تلك الســنه كمــا أن املوظــف ‪............‬إمنا هو‬\n‫محاســب وليــس مهنــدس وال عالقــة لــه بصيانــة تلــك األجهــزة وقــد غــادر‬\n‫إلــى بلــده بتأشــيرة خــروج نهائــي برقــم ‪ 52526942‬يف ‪1426/11/19‬ه ـ‬\n‫هــذا هــو ملخــص جوابــي ثــم جــرى إفهــام املدعــى عليــه وكالــة بــأن‬\n‫وكالتــه التــي قدمهــا ال تخولــه اإلقــرار واإلنــكار والبــد مــن ذلــك فقــرر‬\n‫قائــا أطلــب إمهالــي إلحضــار وكالــة تخولنــي ذلــك يف اجللســة القادمــة‬\n‫فأجيــب لذلــك كمــا جــرى إفهامــه أيضــا بإحضــار رده علــى مــا جــاء يف‬\n‫رد املدعــي وكالــة فاجللســة القادمــة ثــم قــرر املدعــي وكالــة قائــا لقــد‬\n\n\n                                                                                      ‫‪54‬‬\n\f     ‫مللــت مــن متابعــة هــذه القضيــة حيــث طــال أمــر النظر فيهــا وأطلب البت‬\n     ‫فيهــا بحكــم يف هــذا اليــوم هكــذا قــرر ثــم أفهمتــه مــن انــه البــد مــن‬\n     ‫إكمــال مــا طلــب أنفــا فقــال إننــي ال أريــد أن يكمــل أي شــي يف هــذه‬\n     ‫القضيــة وأطلــب البــت فيهــا بحكــم حيــث ســبق أن راجعــت املســئولني‬\n     ‫يف املجلــس األعلــى للقضــاء فأفادونــي شــفهيا بــان هــذه القضيــة صاحلــة‬\n     ‫للحكــم فيهــا ولــك أن تطلــب مــن ناظــر القضيــة احلكــم فيهــا حــاال‬\n     ‫هكــذا قــرر فبنــاء علــى مــا ســبق مــن الدعــوى واإلجابــة ونظــرا ألن‬\n     ‫وكالــة املدعــى عليــه ال تخولــه اإلقــرار والن املدعــي وكالــة طلــب‬\n     ‫البــت فيهــا بحكــم يف هــذه اجللســة والن املدعــي وكالــة رفــض أن‬\n     ‫ميهــل املدعــى عليــه وكالــة إلكمــال مــا طلبنــاه أنفــا والن ذلــك يتعلــق‬\n     ‫مببلــغ قــدره مائــة وتســعون ألــف ريــال وألن املدعــي وكالــة قــد أحضــر‬\n     ‫بيناتــه علــى مجمــوع املبلــغ املدعــى بــه وقــد تبلــغ املدعــى عليــه وكالــة‬\n     ‫باملواعيــد احملــددة لنظــر هــذه الدعــوى لذلــك فقــد ألزمــت الشــركة‬\n     ‫املدعــى عليهــا بــان تدفــع للشــركة املدعيــة مبلغــا قــدره مائتــان وخمســة‬\n     ‫عشــر ألفــا وتســعمائة وخمســون ريــاال وصرفــت النظــر عــن مــا زاد عــن‬\n     ‫ذلــك وقــدرة مائــة وتســعون ألــف ريــال نظــرا الن املدعــي وكالــة قــد‬\n     ‫طلــب البــت يف هــذه القضيــة بحكــم قبــل إكمــال مــا يتعلــق بهــذا املبلــغ‬\n     ‫الــذي دفــع املدعــى عليــه وكالــة بوجــود عطــل فيــه وبذلــك حكمــت‬\n     ‫وأفهمــت املدعــي وكالــة بــان لــه إقامــة دعــوى مســتقلة للمطالبــة باملبلــغ‬\n     ‫الــذي صرفــت النظــر عنــه متــى مــا رغــب يف ذلــك وبعرضــه عليهمــا قنــع‬\n     ‫بــه املدعــى عليــه وكالــة ولــم يقنــع بــه املدعــي وكالــة وطالــب بتمييــزه‬\n     ‫فأجيــب لطلبــه وافهــم بــان عليــه اســتالم نســخة احلكــم يف هــذا اليــوم‬\n     ‫وتقــدمي اعتراضــه خــال مــدة أقصاهــا ثالثــون يومــا مــن تاريــخ اســتالم‬\n\n\n‫‪55‬‬\n\f‫نســخة احلكــم وان لــم يقــدم اعتراضــه خــال هــذه املــدة فــان حقــه‬\n‫يســقط يف االعتــراض ويصبــح احلكــم مكتســبا للقطعيــة وفهــم ذلــك‬\n‫واســتعد بــه وعليــه جــرى التوقيــع وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                           ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/06/14‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ويف يــوم الثالثــاء املوافــق ‪1433/11/9‬هـ افتتحت‬\n‫اجللســة يف الســاعة الثامنــة وخمــس وأربعــن دقيقــة صباحــا بنــاء علــى‬\n‫ورود املعاملــة مــن محكمــة االســتئناف بالقصيــم برقــم (‪)331333322‬‬\n‫يف (‪1433/9/13‬ه ـ ) مــزودة بقــرار أصحــاب الفضيلــة قضــاة‬\n‫االســتئناف بالدائــرة احلقوقيــة األولــى مبحكمــة االســتئناف بالقصيــم‬\n‫رقــم ‪ 33398161‬يف ‪1433/8/28‬ه ـ املقــرر فيــه مــا نــص احلاجــة منــه ((‬\n‫وبدارســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة‬\n‫‪ ،‬فإننــا نقــرر بعــث هــذه املعاملــة لفضيلــة حاكــم القضيــة إلرفــاق مــا‬\n‫يلــي ‪ :‬أوال‪ :‬أســاس معاملــة نظــر القضيــة الســابقة لديــه واملرفــق بهــا‬\n‫قــرار الدائــرة احلقوقيــة مبحكمــة االســتئناف رقــم (‪/125‬ق‪/‬أ) يف‬\n‫‪1431/10/25‬ه ـ املرفقــة صورتــه ‪ .‬ثانيــا‪ :‬إرفــاق أصــل الصــك الصــادر‬\n‫مــن فضيلتــه برقــم (‪/8/70‬ض) يف ‪1431/7/29‬ه ـ ‪ .‬ثالثــا‪ :‬صــورة‬\n‫الضبــط املرفقــة غيــر واضحــة بســبب قلــة احلبــر وعلــى فضيلتــه إرفــاق‬\n‫صــورة ضبــط للقضيــة موثقــة تكــون واضحــة تســهل قراءتهــا ومالحظــة‬\n‫مثــل ذلــك مســتقبال ثــم إعــادة املعاملــة بعــد اســتكمال املطلــوب لكــي‬\n‫تتــم دراســتها ‪ .‬ملالحظــة ذلــك )) وعليــه فقــد مت إرفــاق املطلــوب يف‬\n‫الفقــرات الثــاث وعليــه جــرى التوقيــع وصلــى اهلل وســلم علــى نبينــا‬\n                                              ‫محمــد حــرر يف ‪1433/11/9‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد يف يــوم االربعــاء املوافــق ‪1434 / 2/20‬هـ افتتحت‬\n\n\n                                                                                 ‫‪56‬‬\n\f     ‫اجللســة يف الســاعة احلاديــة عشــر صباحــا بنــاء علــى ورود املعاملــة مــن‬\n     ‫محكمــة االســتئناف بالقصيــم برقــم (‪ )34117830‬يف‪1434/2/10‬ه ـ‬\n     ‫مــزودة بقــرار أصحــاب الفضيلــة قضــاة االســتئناف بالدائــرة احلقوقيــة‬\n     ‫األولــى مبحكمــة االســتئناف بالقصيــم رقــم (‪ )33476868‬يف‬\n     ‫‪1433/12/25‬ه ـ املقــرر فيــه مــا نــص احلاجــة منــه ((وباالطــاع علــى مــا‬\n     ‫أجــاب بــه فضيلتــه علــى قرارنــا رقــم (‪ )33398161‬يف ‪1433/8/28‬ه ـ‬\n     ‫لوحــظ أن فضيلتــه لــم يكمــل املطلــوب علــى املالحظــة الثالثــة مــن‬\n     ‫القــرار املشــار إليــه وال بــد مــن ذلــك لتمكــن الدائرة مــن تدقيق القضية‬\n     ‫ملالحظــة ذلــك ))أ‪.‬هــ‪ .‬وعليــه فإننــي أمرت ســابقا بإعــادة تصوير الضبط‬\n     ‫مــن جديــد لكــن هــذا هــو مســتوى آالت التصويــر املؤمنــة مــن قبــل‬\n     ‫الــوزارة ومــع ذلــك فقــد أمــرت بإرفــاق صــورة أخــرى جديــدة مصدقــة مــن‬\n     ‫ضبــط القضيــة ثــم إعادتهــا إلــى محكمــة االســتئناف لتدقيقهــا وعليــه‬\n                         ‫جــرى التوقيــع ‪ ،‬وصلــى اهلل وســلم علــى نبينــا محمــد ‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد يف يــوم األحــد املوافــق ‪1434/3/29‬ه ـ افتتحــت‬\n     ‫اجللســة يف الســاعة الواحــدة والنصــف ظهــرا بنــاء علــى ورود املعاملــة مــن‬\n     ‫محكمــة االســتئناف بالقصيــم برقــم (‪ )34483606‬يف ‪1434/3/24‬ه ـ‬\n     ‫مــزودة بقــرار أصحــاب الفضيلــة قضــاة االســتئناف بالدائــرة احلقوقيــة‬\n     ‫األولــى مبحكمــة االســتئناف بالقصيــم رقــم (‪ )3463820‬يف‬\n     ‫‪1434/3/16‬ه ـ املقــرر فيــه ( باألكثريــة املصادقــة علــى احلكــم مــع‬\n     ‫التنبيــه إلــى تصديــق الــوكاالت املرفقــه وتصحيــح لقــب املدعــي وكالــة‬\n     ‫نظــرا ألن اســمه ‪ ...........‬وليــس ‪..........‬أ‪.‬هــ‪ .‬وقــد جــرى منــا تصديــق‬\n     ‫الــوكاالت وأمــا لقــب املدعــي وكالــة فــإن صحتــه ‪ .............‬يف كل‬\n     ‫موضــع ذكــر فيــه وعليــه جــرى التوقيــع ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n\n\n‫‪57‬‬\n\f                  ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/03/29‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى نبينــا محمــد وعلى آلــه وصحبه‬\n‫وبعــد‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة احلقوقيــة األولــى مبحكمــة‬\n‫االســتئناف مبنطقــة القصيــم علــى املعاملــة الــواردة مــن فضيلــة رئيــس‬\n‫ال ـمـ ــحكمة الـ ـع ــام ـ ــة يف محافظــة عنيــزة ب ــرق ـ ــم (‪)34367743‬‬\n‫وتــاري ـ ــخ ‪1434/2/24‬ه ـ ؛ احملالــة إلينــا برقــم (‪)3494555‬؛ الــمرف ـ ــق‬\n‫بها ال ـصـ ــك الــمسج ـ ــل ب ــرق ــم (‪ )33296287‬وت ــاريـ ــخ ‪1433/6/14‬هـ‬\n‫؛ الصــادر مــن فضيلــة الشــيخ‪ ............ /‬القاضــي باحملكمــة؛ اخلــاص‬\n‫بدعــوى‪ ............ /‬الوكيــل عــن‪ ............. /‬صاحــب مؤسســة ‪..........‬‬\n‫لألجهــزة الطبيــة؛ ضــد‪ ................ /‬الوكيــل عــن‪ /‬شــركة ‪..............‬‬\n‫‪ ،‬بشــأن املطالبــة مببلــغ مالــي قيمــة معــدات طبيــة‪ ،‬وقــد تضمــن الصــك‬\n‫حكــم فضيلتــه بإلــزام الشــركة املدعــى عليهــا بــأن تدفــع للمؤسســة‬\n‫املدعيــة مبلغ ـ ًا وقــدره مائتــان وخمســة عشــر ألف ـ ًا وتســعمائة وخمســون‬\n‫ريــا ًال وصــرف النظــر عمــا زاد عــن ذلــك؛ علــى النحــو املفصــل فيــه‪،‬‬\n‫وقــد ســبق منــا دراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة‬\n‫وأوراق املعاملــة وباالطــاع علــى مــا أجــاب بــه فضيلتــه علــى قرارنــا‬\n‫رقــم (‪ )3430584‬يف ‪1434/2/5‬هـ ـ فإننــا نقــرر باألكثريــة املصادقــة‬\n‫علــى احلكــم بعــد اإلجــراء األخيــر مــع تنبيــه فضيلــة القاضــي إلــى مــا‬\n‫يلــي‪ :‬أوالً‪ :‬تصديــق صورتــي وكالتــي املدعــي واملدعــى عليــه املرفقتــن‬\n‫باملعاملــة ومالحظــة ذلــك مســتقبالً‪ .‬ثانيـاً‪ :‬تصحيــح لقــب املدعــي وكالة‬\n‫يف الضبــط والصــك ‪ ،‬حيــث ذكــر أن لقبــه (‪ )............‬والصــواب‬\n‫(‪ ).............‬ليطابــق مــا يف ســجله املدنــي وصــك وكالتــه‪ .‬واهلل املوفــق‪،‬‬\n                      ‫وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n                                                                                   ‫‪58‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"17250706-b6cd-5618-b1f0-019e3dec82ff","source_page_start":49,"source_page_end":58,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"81df7d8122211cdada44a732cf4a1450723820a4d757bf583ed949f0dfb9f730","normalized_text_hash":"03ddb69c511eb85440ab5a7d1b2c0f5bc1919a25be4dacdf740936bb32de3823","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v1-p49-33296287"},{"id":"79479f0c-d9e2-56d4-af16-a51175515836","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -عقار -شراء فله مع حوش -االختاف بن املتعاقدين يف األقساط -بيع املرهون ال يتم إال بإذن املرتهن -بطان عقد","document_number":"3419890","case_number":"2179","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/21","year":"1434","subject":"بيع -عقار -شراء فله مع حوش -االختاف بن املتعاقدين يف األقساط -بيع املرهون ال يتم إال بإذن املرتهن -بطان عقد","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1434/1/21 :‬هـ‬\n                     ‫ُ‬                ‫َر ْق ُم َّ‬\n                         ‫الص ِّك‪3419890 :‬‬\n                            ‫َر ْق ُم الدعوى‪2179 :‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34178272‬تاريخه‪1434/4/3 :‬هـ‬\n\n\n     ‫بيــع ‪ -‬عقــار ‪ -‬شــراء فلــه مــع حــوش ‪ -‬االختــاف بــن املتعاقديــن‬\n     ‫يف األقســاط ‪ -‬بيــع املرهــون ال يتــم إال بــإذن املرتهــن ‪ -‬بطــان عقــد‬\n                                                                      ‫املبايعــة ‪.‬‬\n\n\n\n\n     ‫مــا نــص عليــه أهــل العلــم مــن أنــه ال يحــق للراهــن أن يتصــرف يف‬\n                                 ‫العــن املرهونــة إال بــإذن مــن املرتهــن ‪.‬‬\n\n\n\n\n     ‫ادعــى املدعــي بأنــه اشــتري مــن املدعــى عليــه فلــه مــن دوريــن مــع‬\n     ‫احلــوش املجــاور لهــا مببلــغ أربعمائــة ألــف ريــال مقســطة ‪ -‬دفــع منهــا‬\n     ‫ســبعة وخمســن ألــف ريــال ‪ -‬حــل أربعــن ألــف ريــال يف ‪1430/1/1‬ه ـ‬\n     ‫وامتنــع املدعــى عليــه مــن اســتالمها ‪ -‬طلــب املدعــي إلــزام املدعــى عليــه‬\n     ‫بإخــاء الــدور الثانــي مــن الفلــة واســتالم القســط املذكــور ‪ -‬أجــاب‬\n     ‫املدعــى عليــه بــأن الفلــة املذكــورة ملــك لــه ومســجله باســم والدتــه‬\n     ‫واحلــوش ملــك لــه ‪ -‬قــرر املدعــى عليــه انــه ال مانــع لديــة مــن اإلخــاء‬\n     ‫إذا دفــع املدعــي املبلــغ احلــال البالــغ قــدره مائــة وثالثــة وثمانــون ألــف‬\n     ‫ريــال ‪ -‬قــرر املدعــي بــأن احلــال أربعــن ألــف ريــال الواصــل منهــا خمســة‬\n     ‫آالف ‪ -‬حصــل اختــاف بــن الطرفــن يف األقســاط وكيفيــة الســداد‬\n‫‪59‬‬\n\f‫‪ -‬احضــر املدعــى ثالثــة شــهود‪ ،‬شــهدوا علــى صحــة مــا ذكــره‪ -‬أقــر‬\n‫املدعــى عليــه بصحــة الشــهادة ‪ -‬جــرى تعديــل الشــهود ‪ -‬جــرى االطــاع‬\n‫علــى صــورة الصــك وهــو مرهــون لصالــح صنــدوق التنميــة العقــاري‪-‬‬\n‫جــرت الكتابــة للصنــدوق العقــاري لإلفــادة عــن موافقتــه علــى بيــع‬\n‫العقــار موضــع الدعــوى علــى املدعــي ( املشــتري) ورد اجلــواب بــأن‬\n‫املدعــي لديــه طلــب قــرض ولكــي يتــم نقــل العقــار ورصيــد القــرض إليــه‬\n‫فــا بــد مــن إلغــاء طلــب قرضــه إذ ال ميكــن اجلمــع بــن طلــب القــرض‬\n‫ونقــل ملكيــة العقــار املرهــون لصالــح الصنــدوق إليــه وقــد طلــب منــه‬\n‫فتــح ملــف مبايعــة بشــرط إلغــاء طلــب قرضــه ورفــض هــذا الشــرط وبنــاء‬\n‫عليــه فــإن الصنــدوق ال يوافــق علــى نقــل العقــار محــل النــزاع ورصيــد‬\n‫القــرض إلــى املدعــي مــادام احلــال مــا ذكــر ‪ -‬جــرى ســؤال املدعــي عــن‬\n‫املبلــغ الــذي ســلمه للمدعــى عليــه فذكــر أنــه ســبعة وخمســن ألــف ريــال‬\n‫وصــادق املدعــى عليــه علــى ذلــك ‪ -‬ملــا قــرره أهــل العلــم مــن أنــه ال يحــق‬\n‫للراهــن أن يتصــرف يف العــن املرهونــة إال بــإذن مــن املرتهــن وألن املرتهن‬\n‫وهــو صنــدوق التنميــة العقــاري لــم يجــز هــذا البيــع لــذا صــدر احلكــم‬\n‫ببطــان عقــد البيــع املذكــور وإلــزام املدعــي بتســليم العقــار للمدعــى‬\n‫عليــه وإلــزام املدعــى عليــه بإعــادة مــا اســتلمه مــن املدعــى وقــدرة ســبعة‬\n‫وخمســون ألــف ريــال ‪ -‬اعتــرض الطرفــان علــى احلكــم ‪ -‬صــدق احلكــم‬\n                                                      ‫مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...‬القاضــي يف احملكمــة العامــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n\n                                                                                       ‫‪60‬‬\n\f     ‫العامــة بالريــاض برقــم ‪ 2179‬وتاريــخ ‪ 1430/01/10‬ه ـ املقيــدة‬\n     ‫باحملكمــة برقــم ‪ 306535‬وتاريــخ ‪ 1430/01/10‬ه ـ ويف يــوم األربعــاء‬\n     ‫املوافــق‪ 1430/04/12‬ه ـ حضــر ‪...‬ســعودي اجلنســية مبوجــب الســجل‬\n     ‫املدنــي رقــم ‪...‬وادعــى علــى احلاضــر معــه ‪...‬ســعودي اجلنســية مبوجــب‬\n     ‫الســجل املدنــي رقــم ‪...‬قائــا اشــتريت مــن املدعــى عليــه فلــه دوريــن‬\n     ‫مســاحتها أربعمائــة متــر مبوجــب الصــك الصــادر مــن كتابــة عــدل‬\n     ‫الريــاض األولــى برقــم ‪ 13/19923‬وتاريــخ ‪1417/3/16‬ه ـ وبجوارهــا‬\n     ‫حــوش مــن شــرق مســاحته خمســمائة متــر مربــع بأربعمائــة ألــف‬\n     ‫ريــ‪ 400.000‬ــال مقســطة دفعت منها أثنني وخمســن ألف ريـ‪ 52000‬ــال‬\n     ‫وكذلــك خمســة االف ريــ‪ 5000‬ــال وقــد حــل أربعــن ألــف ريــال يف‬\n     ‫‪1430/1/1‬ه ـ أمتنــع مــن اســتالمها فأطلــب إلزامــه بإخالء الــدور الثاني‬\n     ‫واســتالم القســط هــذه دعــواي وبســؤال املدعــى عليــه أجــاب بقولــه أن‬\n     ‫الفلــة املذكــورة هــي ملــك لــي ومســجله باســم والدتــي رحمهــا اهلل‬\n     ‫واحلــوش ملكــي وال مانــع مــن األخــاء إذا دفــع احلــال ومقــداره مائــة‬\n     ‫وثالثــة وثمانــن ألــف ريــ‪ 183000‬ــال هكــذا أجــاب وبعــرض ذلــك علــى‬\n     ‫املدعــي قــال احلــال أربعــن ألــف ريــ‪ 40.000‬ــال وصــل منهــا خمســة وال‬\n     ‫مانــع مــن دفــع خمســة وثالثني ألف ريــ‪ 35000‬ــال والعقــود مرفق صورها‬\n     ‫باملعاملــة ثالثــة عقــود ويف يــوم االثنــن املوافق‪1431/3/22‬ه ـ لــدي أنــا‬\n     ‫‪...‬القاضــي باحملكمــة العامــة بالريــاض خلــف فضيلــة الشــيخ ‪...‬وفيهــا‬\n     ‫حضــر الطرفــان و بتــاوة مــا ضبــط ســابق ًا عليهمــا صــادق كل واحــد‬\n     ‫منهمــا علــى مــا نســب إليــه فيــه وبســؤال املدعــي عــن املبالــغ احلالــة حاليـ ًا‬\n     ‫فقــال إن مقــدار املبلــغ احلــال و املســتحق يف ذمتــي مبلــغ و قــدره خمســة و‬\n     ‫ســبعون ألــف ريــال و الباقــي يحــل علــى أقســاط ســنوية مقــدار كل‬\n\n\n‫‪61‬‬\n\f‫قســط أربعــون ألــف ريــال بتاريــخ ‪ 1/1‬مــن كل عــام حتــى انتهــاء املبلــغ‬\n‫املتفــق عليــه وقــدره أربعمائــة ألــف ريــال وبعــرض ذلــك علــى املدعــى عليــه‬\n‫قــال مــا ذكــره املدعــي غيــر صحيــح و الصحيــح أننــي بعتــه العمــارة‬\n‫املذكــورة مــع احلــوش املذكــور مببلــغ و قــدره أربعمائــة ألــف ريــال تســلم‬\n‫علــى دفعتــن الدفعــة األولــى حالــة و قدرهــا مئتــا ألــف ريــال و الدفعــة‬\n‫الثانيــة و قدرهــا مئتــا ألــف ريــال علــى أقســاط ســنوية قدرهــا أربعــون‬\n‫ألــف ريــال كمــا أننــي اشــترطت عليــه يف عقــد املبايعــة أنــه يف حالــة‬\n‫ســقوط قــرض الصنــدوق وتنــازل الصنــدوق عنــه بناء علــى األمر امللكي‬\n‫القاضــي بإســقاط القــروض عــن املقتــرض املتوفــى فإنــه يلتــزم لــي بدفــع‬\n‫مبلــغ و قــدره مئــة ألــف ريــال إضافــة للمبلــغ املتفــق عليــه املذكــور أعــاه‬\n‫ويف حالــة عــدم إســقاط القــرض فإنــه يلتــزم بســداده للصنــدوق ولــدي مــا‬\n‫يثبــت ذلــك و بعــرض ذلــك علــى املدعــي قــال مــا ذكــره املدعــى عليــه‬\n‫غيــر صحيــح ولــم يــدون ذلــك بعقــد املبايعــة وبعــرض ذلــك علــى املدعــى‬\n‫عليــه قــال الصحيــح مــا ذكرتــه يف إجابتــي وبســؤاله ابــرز ورقــه مؤرخــه‬\n‫يف ‪1431/3/23‬ه ـ واملتضمنــة مــا نصــه (بنــاء علــى اتفــاق الطرفــن علــى‬\n‫مبايعــة الفلــه الواقعــة باحلائــر بــاع الطــرف األول ‪ ...‬والطــرف الثانــي‬\n‫‪...‬مببلــغ وقــدره أربعمائــة ألــف ريــال ســلم فيهــا اثنــان وخمســون ألف ريال‬\n‫والباقــي ثالثمائــة وثمانيــة وأربعــون ألــف ريــال فيهــا مائــه وثمانيــة‬\n‫وأربعــون ألــف ريــال مقاطيــع حســب اتفــاق الطرفــن والباقــي مائتــن‬\n‫ألــف ريــال مقســطه كل ســنه أربعــن ألــف ريــال وعلــى طلــب البائــع‬\n‫اعطــي هــذا التوضيــح وصلــى اهلل علــى ســيدنا محمــد ‪ .‬كتبــه يشــهد بــه‬\n‫‪...‬توقيعــه) ‪ .‬وبعــرض ذلــك علــى املدعــي قــال الصحيــح مــا ذكرتــه يف‬\n‫دعــواي ومــا جــاء يف اإلقــرار املذكــور غيــر صحيــح أحضــر ‪ ...‬ســعودي‬\n\n\n                                                                                       ‫‪62‬‬\n\f     ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬وبســؤاله عمــا لديــه مــن شــهادة‬\n     ‫قــال أشــهد اهلل أننــي حضــرت مجلــس البيــع الــذي مت بــن املدعــي ‪...‬‬\n     ‫واملدعــى عليــه ‪...‬هذيــن احلاضريــن معــي وقــد بــاع ‪...‬علــى ‪...‬عمارتــه‬\n     ‫املكونــة مــن دوريــن وحــوش باجلهــة الشــرقية مــن العمــارة مبســاحة‬\n     ‫خمســمائة متــر مربــع (‪500‬م‪ )2‬مببلــغ إجمالــي وقــدره أربعمائــة ألــف‬\n     ‫ريـ‪ 400000‬ــال وقــد ســلم املشــتري مــن قيمــة العمــارة مائــة وأربعــة مــن‬\n     ‫الغنــم مببلــغ وقــدره اثنــان وخمســون ألــف ريـ‪ 52000‬ــال والباقــي مــن‬\n     ‫قيمــة العمــارة واحلــوش مبلــغ وقــدره ثالثمائــة وثمانيــة وأربعــون ألــف‬\n     ‫ريـ‪ 348000‬ــال اتفقــا الطرفــان علــى أن يقــوم املدعــي املشــتري بســدادها‬\n     ‫للمدعــى عليــه علــى أقســاط ســنوية مقــدار كل قســط أربعــون ألــف‬\n     ‫ريــال اعتبــارا مــن ‪1430/1/1‬ه ـ كمــا اتفقــا علــى انــه إذا حصــل لــدى‬\n     ‫املدعــي معاريــض وقبلهــا املدعــى عليــه فيتــم حســابها مــن القســط املتفــق‬\n     ‫عليــه وإذا لــم يحصــل معاريــض فهمــا علــى مــا اتفقــا عليــه كمــا اتفقــوا‬\n     ‫علــى أن يقــوم البائــع بســداد األقســاط املســتحقة لصنــدوق التنميــة‬\n     ‫العقاريــة إال إذا حصــل إعفــاء مــن القســط هــذا مــا لــدي مــن شــهادة ‪.‬‬\n     ‫و‪...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬وبســؤاله عمــا لديــه‬\n     ‫مــن شــهادة قــال أشــهد اهلل أننــي حضــرت مجلــس البيــع الــذي مت بــن‬\n     ‫املدعــي ‪...‬واملدعــى عليــه ‪...‬هذيــن احلاضريــن معــي وقــد بــاع ‪...‬علــى ‪...‬‬\n     ‫عمارتــه املكونــة مــن دوريــن وحــوش باجلهــة الشــرقية مــن العمــارة‬\n     ‫مبســاحة خمســمائة متــر مربــع (‪500‬م‪ )2‬مببلــغ إجمالــي وقــدره أربعمائــة‬\n     ‫ألــف ريـ‪ 400000‬ــال وقــد ســلم املشــتري مــن قيمــة العمــارة مائــة وأربعــة‬\n     ‫مــن الغنــم مببلــغ وقــدره اثنــان وخمســون ألــف ريـ‪ 52000‬ــال والباقــي مــن‬\n     ‫قيمــة العمــارة واحلــوش مبلــغ وقــدره ثالثمائــة وثمانيــة وأربعــون ألــف‬\n\n\n‫‪63‬‬\n\f‫ريـ‪ 348000‬ــال اتفــق الطرفــان علــى ان يقــوم املدعــي املشــتري بســدادها‬\n‫للمدعــى عليــه علــى أقســاط ســنوية مقــدار كل قســط أربعــون ألــف‬\n‫ريــال اعتبــارا مــن ‪1430/1/1‬ه ـ كمــا اتفقــا علــى انــه إذا حصــل لــدى‬\n‫املدعــي معاريــض وقبلهــا املدعــى عليــه فيتــم حســابها مــن القســط املتفــق‬\n‫عليــه وإذا لــم يحصــل معاريــض فهمــا علــى مــا اتفقــا عليــه كمــا اتفقــوا‬\n‫علــى أن يقــوم البائــع بســداد األقســاط املســتحقة لصنــدوق التنميــة‬\n‫العقاريــة إال إذا حصــل إعفــاء مــن القســط هــذا مــا لــدي مــن شــهادة ‪.‬‬\n‫و‪...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬وبســؤاله أشــهد اهلل‬\n‫أننــي ‪ ...‬حضــرت مجلــس البيــع الــذي مت بــن املدعــي ‪...‬واملدعــى عليــه‬\n‫‪...‬هذيــن احلاضريــن معــي وقــد بــاع ‪...‬علــى ‪...‬عمارتــه املكونــة مــن دوريــن‬\n‫وحــوش باجلهــة الشــرقية مــن العمــارة مبســاحة خمســمائة متــر مربــع‬\n‫(‪500‬م‪ )2‬مببلــغ إجمالــي وقــدره أربعمائــة ألــف ريـ‪ 400000‬ــال وقــد ســلم‬\n‫املشــتري مــن قيمــة العمــارة مائــة وأربعــة مــن الغنــم مببلــغ وقــدره اثنــان‬\n‫وخمســون ألــف ريـ‪ 52000‬ــال والباقــي مــن قيمــة العمــارة واحلــوش مبلــغ‬\n‫وقــدره ثالثمائــة وثمانيــة وأربعــون ألــف ريـ‪ 348000‬ــال اتفقــا الطرفــان‬\n‫علــى أن يقــوم املدعــي املشــتري بســدادها للمدعــى عليــه علــى أقســاط‬\n‫ســنوية مقــدار كل قســط أربعــون ألــف ريــال اعتبــارا مــن ‪1430/1/1‬ه ـ‬\n‫كمــا اتفقــا علــى انــه إذا حصــل لــدى املدعــي معاريــض وقبلهــا املدعــى‬\n‫عليــه فيتــم حســابها مــن القســط املتفــق عليــه وإذا لــم يحصــل معاريــض‬\n‫فهمــا علــى مــا اتفقــا عليــه كمــا اتفقــوا علــى أن يقــوم البائــع بســداد‬\n‫األقســاط املســتحقة لصنــدوق التنميــة العقاريــة إال إذا حصــل إعفــاء مــن‬\n‫القســط هــذا مــا لــدي مــن شــهادة ‪ .‬وبعــرض الشــهود وشــهادتهم علــى‬\n‫املدعــى عليــه قــال أمــا الشــهود فــا أقــول فيهــم إال خيــرا وشــهادتهم‬\n\n\n                                                                                       ‫‪64‬‬\n\f     ‫صحيحــة عــدا مــا ذكــروه بخصــوص مــا يتعلــق بصنــدوق التنميــة‬\n     ‫العقاريــة فقــد كان االتفــاق بيننــا علــى أن يقــوم املدعــي مبتابعــة‬\n     ‫إجــراءات اإلعفــاء لــدى صنــدوق التنميــة فــإذا مت اإلعفــاء و إال فيتحمــل‬\n     ‫باقــي أقســاط صنــدوق التنميــة باإلضافــة أن االتفــاق الــذي مت بيننــا‬\n     ‫كان علــى أن يقــوم بتســليم مائتــا ألــف ريــال والباقــي علــى أقســاط‬\n     ‫ســنوية كل ســنة أربعــون ألــف ريــال وبســؤال املدعــي هــل لديــه بينــة غيــر‬\n     ‫مــا احضــر فقــال ال بينــة لــدي ســوى مــن أحضــرت وبطلبــي تعديــا‬\n     ‫للشــهود املذكوريــن فقــال أننــي مســتعد بإحضارهــم يف اجللســة القادمــة‬\n     ‫وبســؤال املدعــى عليــه هــل لديــه بينــة علــى صحــة مــا جــاء يف إجابتــه قــال‬\n     ‫إن الشــاهد ‪ ...‬امتنــع مــن احلضــور للمحكمــة وقــال إنــه ليــس لديــه ســوى‬\n     ‫مــا جــاء يف الورقــة التــي وقعهــا واملؤرخــة يف ‪1431/3/23‬ه ـ فجــرى‬\n     ‫ســؤاله هــل لديــه بينــة غيــر مــا ذكــر فقــال ال بينــة ســوى مــا ذكرتــه‬\n     ‫وبســؤال املدعــي عمــا وعــد بــه يف اجللســة املاضيــة فقــال إننــي مســتعد‬\n     ‫بإحضــار معدلــن للشــهود وجــرى ســؤاله عــن صــك امللكيــة للفيلــة‬\n     ‫موضــع الدعــوى فأبــرز الصــك الصــادر مــن كتابــة عــدل الريــاض برقــم‬\n     ‫‪ 13/19923‬يف ‪1417/3/16‬ه ـ باالطــاع عليــه وجدتــه يتضمــن متلــك‬\n     ‫‪...‬لكامــل اجلــزء الشــرقي مــن قطعــة األرض الواقعــة واملقــام عليهــا فيــا‬\n     ‫دوريــن واملوضحــة أطوالــه وحدودهــا ومســاحتها بباطنــة لــذا وحيــث‬\n     ‫احلــال مــا ذكــر فقــد قــررت رفــع اجللســة للكتابة لكتابة عــدل الرياض‬\n     ‫الستفســار عــن ســريان مفعــول الصــك املذكــور فاحضــر ‪...‬ســعودي‬\n     ‫اجلنســية ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬و‪...‬ســعودي‬\n     ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬وشــهدا بعدالــة وثقــة الشــهود‬\n     ‫املذكوريــن وقــد ســبق أن جــرت الكتابــة منــا لكتابــة العــدل األولــى‬\n\n\n‫‪65‬‬\n\f‫بالريــاض برقــم ‪ 32/1176994‬يف ‪1432/9/17‬ه ـ لالستفســار عــن‬\n‫ســريان مفعــول الصــك رقــم ‪ 13/19923‬يف ‪1417/3/16‬ه ـ فوردنــا‬\n‫خطــاب رئيــس كتابــة العــدل األولــى بالريــاض برقــم ‪ 32/ 49057‬يف‬\n‫‪1432/10/8‬ه ـ واملتضمــن انــه بالبحــث يف ســجالت اإلدارة تبــن أن‬\n‫الصــك رقــم ‪ 13/19923‬يف ‪1417/3/16‬ه ـ ال يوجــد علي ســجل الصك‬\n‫مــا يخــل مبضمونــه علمــا انــه مرهــون للصنــدوق العقــاري ونظــرا لكــون‬\n‫العقــار املشــار إليــه مــا يــزال مرهونــا لصالــح الصنــدوق فقــد قــررت‬\n‫الكتابــة لصنــدوق التنميــة العقاريــة لإلفــادة عــن موافقتهــا علــى بيــع‬\n‫العقــار املشــار إليــه علــى املشــتري املذكــور مــن عدمــه يف يــوم الثالثــاء‬\n‫املوافق‪1433/06/17‬ه ـ لــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n‫بالريــاض خلــف فضيلــة القاضــي ‪ ...‬حضــر الطرفــان وبتــاوة مــا مت‬\n‫ضبطــه عليهمــا صادقــا عليــه وقــد ورد لنــا خطــاب مديــر عــام صنــدوق‬\n‫التنميــة العقاريــة ‪ 33701/2972‬وتاريــخ ‪1433/1/26‬ه ـ املتضمــن أنــه‬\n‫طاملــا العقــار مرهــون لصالــح الصنــدوق فعلــى املشــتري مراجعــة‬\n‫الصنــدوق لفتــح ملــف مبايعــه معــه والتحقــق مــن انطبــاق شــروط‬\n‫االقتــراض عليــه والتفاهــم معــه حــول تســديد األقســاط املســتحقة‬\n‫بالصنــدوق ومــن ثــم ســتتم إجابــة فضيلتكــم بــرأي الصنــدوق حيــال‬\n‫ذلــك ا‪.‬ه ـ وبعــرض ذلــك علــى املدعــي قــال إننــي راجعــت الصنــدوق‬\n‫وطلبــوا منــي تســديد دفعــة مقدمــة وموافقــة جهــة عملــي علــى حســم‬\n‫مبلــغ ألــف ريــال شــهريا و إســقاط اســمي لديهــم فلــم أوافــق علــى ذلــك‬\n‫حيــث أن املدعــى عليــه هــو الــذي اســتعد بتســليم األقســاط املتأخــرة‬\n‫لــدى الصنــدوق هكــذا قــرر لــذا قــررت الكتابــة للصنــدوق لإلفــادة عن‬\n‫موافقتهــم مــن عدمهــا بنــاء علــى مــا قــرره املدعــي وأجلــت إلــى حــن ورود‬\n\n\n                                                                                     ‫‪66‬‬\n\f     ‫اإلجابــة وقــد ورد لنــا خطــاب مديــر عــام اإلدارة العامــة للقــروض‬\n     ‫بصنــدوق التنميــة العقارية رقــم ‪ 33701/20515‬وتاريخ ‪1433/6/30‬هـ‬\n     ‫املتضمــن إفادتهــم بــأن املدعــي لديــه طلــب قــرض ولكــي يتــم نقــل‬\n     ‫العقــار ورصيــد القــرض إليــه حســب شــروط الصنــدوق فالبــد مــن إلغــاء‬\n     ‫طلــب قرضــه إذ ال ميكــن اجلمــع بــن طلــب القــرض ونقــل ملكيــة العقــار‬\n     ‫املرهــون لصالــح الصنــدوق إليــه وقــد طلــب منــه فتــح ملــف مبايعة بشــرط‬\n     ‫ـاء عليــه فــإن الصنــدوق‬ ‫إلغــاء طلــب قرضــه وقــد رفــض هــذا الشــرط وبنـ ً‬\n     ‫ال يوافــق علــى نقــل العقــار محــل النــزاع ورصيــد القــرض إلــى املدعــي مــا‬\n     ‫دام احلــال كمــا ذكــر ا‪،‬ه ـ وبطلــب صــك حصــر الورثــة مــن املدعــى‬\n     ‫عليــه لوالدتــه ابــرز املدعــى عليــه صــك حصــر الورثــة صــادر مــن‬\n     ‫احملكمــة العامــة باخلــرج برقــم ‪ 10/19‬بتاريــخ ‪1430/8/4‬هـ وباالطالع‬\n     ‫عليــه وجدتــه يتضمــن إثبــات وفــاة ‪ ...‬ســعودية بالســجل املدنــي رقــم ‪...‬‬\n     ‫وتاريــخ الوفــاة ‪1420/7/1‬ه ـ وانحصــار ورثتهــا يف ولديهــا ‪...‬و‪ ...‬مــن‬\n     ‫زوجهــا املتوفــى قبلهــا ‪ ...‬وبســؤال املدعــي عــن املبلــغ الــذي مت إيصالــه‬\n     ‫قــال أننــي وصلــت للمدعــى عليــه ســبعة وخمســن ألــف ريــال وصــادق‬\n     ‫علــى ذلــك املدعــى عليــه وبعــد تأمــل الدعــوى واإلجابــة وحيــث أن املدعى‬\n     ‫عليــه قــد بــاع العقــار املوصــوف بالدعــوى وهــو مرهــون لصالــح صنــدوق‬\n     ‫التنميــة العقاريــة والن الصنــدوق لــم يوافــق علــى نقــل العقــار إلــى املدعــي‬\n     ‫حســب مــا ورد يف خطابــه املذكــور بعاليــه وحيــث نــص أهــل العلــم علــى‬\n     ‫انــه ال يحــق للراهــن أن يتصــرف يف العــن املرهونــة إال بــإذن مــن املرتهــن‬\n     ‫والن املرتهــن وهــو صنــدوق التنميــة العقــاري لــم يجــز هــذا البيــع لــذا‬\n     ‫حكمــت ببطــان عقــد املبايعــة بــن الطرفــن والزمــت املدعــي بتســليم‬\n     ‫العقــار للمدعــى عليــه كمــا الزمــت املدعــى عليــه بإعــادة مبلــغ مــا‬\n\n\n‫‪67‬‬\n\f‫اســتلمه مــن املدعــي وقــدره ســبعة وخمســون ألــف ريــال وبعــرض احلكــم‬\n‫علــى الطرفــن قــررا عــدم القناعــة وطلبــا االســتئناف وأجيــب لطلبهمــا‬\n‫وافهمــا بــان عليهمــا املراجعــة بتاريــخ ‪1434/1/25‬ه ـ الســتالم نســخة‬\n‫مــن احلكــم وتقــدمي اعتراضهمــا عليــه خــال مــدة ثالثــن يومــا مــن‬\n‫التاريــخ املذكــور ويســقط حقهمــا يف االســتئناف بعــده وبــاهلل التوفيــق‪،‬‬\n‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                               ‫‪1434/01/20‬هـ‬\n‫احلمــد هلل وحــده وبعــد ويف يــوم األحــد املوافــق ‪1434/4/14‬ه ـ افتتحــت‬\n‫اجللســة بنــاء علــى مــا وردنــا مــن فضيلــة الرئيــس برقــم ‪ 306535‬يف‬\n‫‪1434/4/10‬ه ـ شــرحا علــى خطــاب رئيــس محكمــة االســتئناف برقــم‬\n‫‪ 34757427‬يف ‪1434/4/7‬ه ـ وبرفقــه قــرار الدائــرة احلقوقيــة اخلامســة‬\n‫رقــم ‪ 34178272‬يف ‪1434/4/3‬ه ـ واملتضمــن مــا نصــه ( وبدراســة‬\n‫الصــك وصــورة ضبطــه ولالئحتــن االعتراضيتــن واوراق املعاملــة لــم‬\n‫يظهــر مــا يوجــب االعتــراض علــى احلكــم واهلل املوفــق ا‪.‬ه ـ قاضــي‬\n‫االســتئناف ‪...‬ختمــه وتوقيعــه وقاضــي االســتئناف ‪ ...‬ختمــه وتوقيعــه‬\n‫رئيــس الدائــرة ‪...‬ختمــه وتوقيعــه ) وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n     ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/4/14‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اخلامســة لتمييــز‬\n‫القضايــا احلقوقيــة مبحكمــة االســتئناف بالريــاض على املعاملــة الواردة‬\n‫مــن فضيلــة رئيــس احملكمــة العامــة بالريــاض املســاعد برقــم ‪306535‬‬\n‫وتاريــخ ‪1434/3/22‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة القاضي‬\n‫باحملكمــة الشيخ‪.../‬املســجل برقــم ‪ 3419890‬وتاريــخ ‪1434/1/21‬ه ـ‬\n‫اخلــاص بدعوى‪.../‬ضد‪.../‬بشــأن إخــاء عقــار علــى الصفــة املوضحــة‬\n\n\n                                                                                     ‫‪68‬‬\n\f     ‫بالصــك واملتضمــن حكــم فضيلتــه كمــا هــو موضــح بالصــك وبدراســة‬\n     ‫الصــك وصــورة ضبطــه والالئحتــن االعتراضيتــن وأوراق املعاملــة لــم‬\n     ‫يظهــر مــا يوجــب االعتــراض علــى احلكــم‪ .‬واهلل املوفــق وصلــى اهلل علــى‬\n                                             ‫نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪69‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"17250706-b6cd-5618-b1f0-019e3dec82ff","source_page_start":59,"source_page_end":69,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"e24aa6abd5b4bc32b6145f72e84e976fefd994b692896b1083e6cdcfcb878a14","normalized_text_hash":"6112c0d1e187e055e17aeabee3cbda45fd1a5fea740dfc2fccb9df0dc4d000a1","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v1-p59-3419890"},{"id":"ed947e76-d02c-5761-b6de-9d95174afe38","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -بيع سيارة بأقساط شهرية -إنكار املدعى عليه شراء السيارة- تقدمي املدعي وكالة ما يفيد شراء املدعى عليه السيارة -إقرار املدعى عليه بصحة توقيعاته على أوراق الشركة البائعة للسيارة -اإللزام بدفع باقي قيمة السيارة .","document_number":"33408456","case_number":"3244","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالدمام","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/9/11","year":"1434","subject":"بيع -بيع سيارة بأقساط شهرية -إنكار املدعى عليه شراء السيارة- تقدمي املدعي وكالة ما يفيد شراء املدعى عليه السيارة -إقرار املدعى عليه بصحة توقيعاته على أوراق الشركة البائعة للسيارة -اإللزام بدفع باقي قيمة السيارة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1433/9/11:‬هـ‬\n                ‫ُ‬                ‫َر ْق ُم َّ‬\n                   ‫الص ِّك‪33408456 :‬‬\n                      ‫َر ْق ُم الدعوى‪3244 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n       ‫‪ 3415623181‬تاريخه‪1434/1/18 :‬هـ‬\n\n\n‫بيــع ‪ -‬بيــع ســيارة بأقســاط شــهرية ‪ -‬إنــكار املدعــى عليــه شــراء الســيارة‪-‬‬\n‫تقــدمي املدعــي وكالــة مــا يفيــد شــراء املدعــى عليــه الســيارة ‪ -‬إقــرار‬\n‫املدعــى عليــه بصحــة توقيعاتــه علــى أوراق الشــركة البائعــة للســيارة‬\n                                     ‫‪ -‬اإللــزام بدفــع باقــي قيمــة الســيارة ‪.‬‬\n\n\n\n\n‫قــال ابــن القيــم رحمــه اهلل يف الطــرق احلكميــة صفحــة (‪ )11‬مــا نصــه‬\n‫( وباجلملــة فالبينــة اســم لــكل مــا ُيبــن احلــق ويظهــره ومــن خصهــا‬\n‫بالشــاهدين أو األربعــة أو الشــاهد لــم يــوف مســماها حقــه ولــم تــأت‬\n‫البينــة قــط يف القــرآن مــرادا بهــا الشــاهدان وإمنــا أتــت مــرادا بهــا‬\n                                       ‫احلجــة والدليــل والبرهــان ) أ ‪ .‬ه ـ‬\n\n\n\n\n‫ادعــى املدعــي وكالــة بــأن املدعــى عليــه اشــترى مــن الشــركة موكلتــه‬\n‫سيـ ــارة مببلــغ معــن يســدد علــى أق ــساط شهـريـ ــة وقــام بدفــع جــزء منــه‬\n‫والباقــي يف ذمتــه طلــب احلكــم بإلزامــه بدفع هــذا املبلغ‪ ،‬أنكر املدعى‬\n‫عليــه شــراء السيـ ــارة إال أنــه أقـ ــر بصحــة توقيعاتــه علــى األوراق املقدمــة‬\n‫مــن الشــركة عــدا وثيقــة امللكيــة‪ ،‬جرت الكتابــة إلدارة املرور ووردت‬\n‫اإلفــادة بصحــة وثيقــة امللكيــة باســم املدعــى عليــه‪ ،‬قدمــت الشــركة‬\n\n                                                                                        ‫‪70‬‬\n\f     ‫املدعيــة بيانـ ًا موقعـ ًا مــن املدعــى عليــه بقيمــة مــا دفعــه املدعــى عليــه ومــا‬\n     ‫بقــي بذمتــه‪ .‬مــن ك ــل مــا تقــدم فقــد ثبــت أن الســيارة قــد انتقلــت مــن‬\n     ‫ملــك الشــركة إلــى ملــك املدعــى عليــه وباقــي بذمتــه مــن قيمــة الســيارة‬\n     ‫مبلـ ــغ ملــزم بدفعــه حــا ًال للشــركة املدعيــة وبــه حكمــت‪ ،‬وبعــرض‬\n     ‫احلكــم علــى الطرفــن قــرر املدعــي وكالــة قناعتــه وقــرر املدعــى عليــه‬\n           ‫عــدم قناعتــه باحلكــم‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ..........‬القاضــي يف احملكمــة العامــة‬\n     ‫بالدمــام وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n     ‫العامــة بالدمــام برقــم ‪ 3244‬وتاريــخ ‪1429/05/09‬ه ـ املقيــدة‬\n     ‫باحملكمــة برقــم ‪ 2912089‬وتاريــخ ‪1433/05/09‬ه ـ ففــي يــوم االثنــن‬\n     ‫املوافــق ‪1433/02/01‬ه ـ افتتحــت اجللســة الســاعة التاســعة والنصــف‬\n     ‫وفيهــا حضــر ‪ ...............‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n     ‫‪ .............‬الوكيــل الشــرعي عــن ‪ ............‬بوكالتــه عــن ‪ ...........‬بصفتــه‬\n     ‫مديــر ًا للشــركة‪ ................‬مبوجــب الوكالــة الصــادرة مــن كتابــة‬\n     ‫عــدل شــمال محافظــة جــده رقــم ‪ 46296‬يف ‪1432/05/22‬ه ـ وحضــر‬\n     ‫حلضــوره املدعــى عليــه ‪...........‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n     ‫رقــم ‪ .................‬وبســؤال املدعــي وكالــة عــن دعــواه قــال لقــد اشــترى‬\n     ‫هــذا احلاضــر ســيارة نــوع ( ‪ ) ....‬موديــل ‪2006‬م رقــم الشــاص ‪.........‬‬\n     ‫بقيمــة إجماليــة مقدارهــا واحــد وســبعون ألــف وتســعمائة ريــال علــى‬\n     ‫أقســاط شــهرية مقــدار كل قســط ألــف وســبعمائة ريــال مقســطة علــى‬\n     ‫اثنــن وأربعــن شــهر دفــع حتــى اآلن مبلــغ ثالثــة وعشــرون ألــف ريــال‬\n\n‫‪71‬‬\n\f‫والباقــي يف ذمتــه ثمانيــة وأربعــون ألــف وأربعمائــة ريــال اطلــب احلكــم‬\n‫عليــه وإلزامــه بدفــع هــذا املبلــغ هــذه دعــواي وبعــرض ذلــك علــى املدعــى‬\n‫ا جميــع مــا ذكــره املدعــي وكالــة يف دعــواه غيــر‬            ‫عليــه أجــاب قائ ـ ً‬\n‫صحيــح فلــم اشــترى الســيارة املذكــورة يف الدعــوى وليــس بينــي وبــن‬\n‫الشــركة املدعيــة اتفــاق علــى شــراء الســيارة ولــم ادفــع لهــم ريــال واحــد‬\n‫يف هــذه الســيارة وكل مــا يف املوضــوع أن زوج بنــت أختــي ‪................‬‬\n‫ذهبــت معــه إلــى الشــركة املتحــدة حتــى تكفلنــي زوجتــه ولكنــه غــرر‬\n‫بــي مــع الشــركة وجعلنــي أوقــع علــى أوراق كثيــرة ال اعلــم مبضمونهــا‬\n‫علمـ ًا بأننــي أقــرأ و أكتــب هــذا مــا لــدي وبســؤال املدعــي وكالــة عــن‬\n‫بينتــه قــال أن ملــف املدعــى عليــه موجــود عندنــا يف الشــركة وأطلــب‬\n‫إمهالــي إلحضــاره يف اجللســة القادمــة هــذا مــا لــدي ثــم قــال املدعــى عليــه‬\n‫أننــي أقــر بــكل األوراق التــي يقدمونهــا وهــي حتــت توقيعــي ولكــن مــن‬\n‫فرحتــي بالســيارة لــم اعلــم مــا هــو مضمــون املبايعــة ويف يــوم الثالثــاء‬\n‫املوافق ‪1433/02/23‬هـ افتتحت اجللســة الســاعة التاســعة وفيها حضر‬\n‫املدعــي وكالــة ‪ ..........‬وحضــر حلضــوره املدعــى عليــه ‪ .............‬وبســؤال‬\n‫املدعــي وكالــة عمــا طلــب منــه يف اجللســة الســابقة قــدم ملــف الســيارة‬\n‫ومــن ضمــن األوراق املقدمــة منــوذج طلــب شــراء بالتقســيط محــرر علــى‬\n‫مطبوعــات ‪.............‬املــؤرخ يف ‪1427/05/23‬ه ـ املوافق ‪2006/06/19‬م‬\n‫مبــن فيــه نــوع الســيارة وهــي ‪ .....‬موديــل ‪2006‬م فضــي اللــون رقــم‬\n‫الشــاص ‪ ..............‬القيمــة اإلجماليــة واحــد وســبعون ألــف وتســعمائة‬\n‫ريــال علــى اثنــن وأربعــن قســط قيمــة القســط الــف وســبعمائة ريــال‬\n‫اســم املشــتري ‪ ...................‬رقــم بطاقــة األحــوال ‪ .....................‬جهــة‬\n‫العمــل شــرطة الدمــام قســم البحــث اجلنائــي توقيعــه واســم الكفيــل‬\n\n\n                                                                                          ‫‪72‬‬\n\f     ‫‪ ............‬معلوماتــه وتوقيعــه اســم الكفيــل احلضــوري ‪.................‬‬\n     ‫معلوماتــه وتوقيعــه ومــن ضمــن األوراق خطــاب تعريــف بالراتــب يخــص‬\n     ‫املدعــى عليــه صــادر مــن الشــئون اإلداريــة واملاليــة بشــرطة الدمــام برقــم‬\n     ‫‪ 433‬يف ‪1427/05/22‬ه ـ ومــن ضمــن املرفقــات عقــد إيجار للشــقة التي‬\n     ‫يســكن بهــا املدعــى عليــه محــرر علــى مطبوعــات مكتــب ‪..............‬‬\n     ‫للخدمــات العقاريــة برقــم ‪ 61‬يف ‪1426/05/25‬ه ـ ومــن ضمــن األوراق‬\n     ‫ســند قبــض محــرر علــى مطبوعــات الشــركة ‪ ..............‬برقــم ‪503649‬‬\n     ‫يف ‪1427/05/23‬ه ـ املوافــق ‪2006/06/19‬م يتضمــن أن املدعــى عليــه‬\n     ‫دفــع مبلــغ ثالثــة اآلف وتســعمائة ريــال ومتثــل الدفعــة األولــى للســيارة‬\n     ‫كــورال ‪2006‬م مــع توقيعــه ومــن ضمــن األوراق أذن فســخ ســيارة محــرر‬\n     ‫علــى مطبوعــات الشــركة ‪ ................‬برقــم ‪ 168751‬يتضمــن الفســخ‬\n     ‫للســيارة نــوع كــورال موديــل ‪2006‬م رقــم الشــاص ‪ .............‬وجــرى‬\n     ‫تســليمها للمدعــى عليــه مــع توقيعــه ومــن ضمــن األوراق صــورة مــن‬\n     ‫بطاقــة األحــوال وصــورة مــن دفتــر العائلــة وفاتــورة هاتــف وصــورة مــن‬\n     ‫وثيقــة ملكيــة الســيارة صــادرة مــن مــرور الظهــران برقــم ‪5361115‬‬\n     ‫تتضمــن مــا يلــي ‪ :‬اســم املالــك ‪ ...............‬رقــم الهويــة ‪ ...............‬رقــم‬\n     ‫الهيــكل ‪ ...............‬رقــم اللوحــة (( ‪ )) .................‬ســيارة كــورال فضــي‬\n     ‫موديــل ‪2006‬م تاريــخ امللكيــة ‪1427/05/24‬ه ـ ومــن ضمــن األوراق‬\n     ‫اتفاقيــة بيــع ســيارة بالتقســيط محــررة على مطبوعات الشــركة ‪...........‬‬\n     ‫وتتضمــن بيانتــا الســيارة املذكــورة أعاله واســم املشــتري ‪......................‬‬\n     ‫واســم الكفيــل الغــارم ‪...............‬وبعــرض مــا جــاء بــه علــى املدعــى عليــه‬\n     ‫قــال أقــر بــأن جميــع التوقيعــات علــى األوراق املقدمــة لفضيلتكــم‬\n     ‫صحيحــة وتعــود لــي وأن جميــع األوراق مــن خطــاب التعريــف وعقــد‬\n\n\n‫‪73‬‬\n\f‫اإليجــار وفاتــورة الهاتــف جميعهــا صحيحــة وتعــود لــي عــدا صــورة وثيقــة‬\n‫ملكيــة الســيارة غيــر صحيحــة بنــاء علــى ذلــك فســيجري الكتابــة‬\n‫إلدارة املــرور للتحقــق مــن ملكيــة الســيارة هــل جــرى تســجيلها باســم‬\n‫املدعــى عليــه ويف يــوم األحــد املوافــق‪ 1433/09/10‬ه ـ افتتحــت‬\n‫اجللســة الســاعة وفيهــا حضــر ‪ ......................‬ســعودي بالســجل املدنــي‬\n‫رقــم ‪ .................‬بالوكالــة الصــادرة مــن كتابــة عــدل الثانيــة شــمال‬\n‫محافظــة جــدة عــن ‪ .........................‬ســعودي بالســجل املدنــي رقــم‬\n‫‪ ........................‬بوكالتــه عــن ‪ .........................‬بصفتــه مديــر ًا لشــركة‬\n‫‪ ...............‬مبوجــب الوكالــة الصــادرة مــن هــذه اإلدارة برقــم ‪6698‬‬\n‫يف ‪1430/01/20‬ه ـ اجللــد ‪ 7976‬واملخــول لــه يف املرافعــة واملدافعــة‬\n‫وقبــول األحــكام وحضــر حلضــوره املدعــى عليــه ‪ ...............‬ســعودي‬\n‫بالســجل املدنــي رقــم ‪ .............‬وقــد وردنــا خطــاب مديــر مــرور الظهــران‬\n‫رقــم ‪ 6/2631/3/7‬يف ‪1433/06/07‬ه ـ واملتضمــن أن الســيارة نــوع‬\n‫كــورال موديــل ‪2006‬م رقــم اللوحــة ‪ .........‬مت تســجيلها مــن قبــل إدارتهــم‬\n‫بتاريــخ ‪1427/05/24‬ه ـ مبوجــب بطاقــة جمركيــة رقــم ‪ ...........‬يف‬\n‫‪1437/01/21‬ه ـ لصالــح ‪ ..................‬وهــي مجيــره مــن قبــل مؤسســة‬\n‫‪ .............‬للســيارات حســب صورة البطاقة اجلمركية والشــرائح املرفقة‬\n‫مــن احلاســب اآللــي أ ‪ .‬ه ـ وقــد جــرى عــرض ذلــك علــى املدعــى عليــه قــال‬\n‫أن مــا ورد غيــر صحيــح هــذا مــا لــدي فبنــاء علــى الدعــوى واإلجابــة‬\n‫وجميــع مــا تقــدم وبعــد االطــاع علــى مــا أبرزتــه الشــركة املدعيــة مــن‬\n‫أوراق ال ميكــن أن تكــون بحوزتهــا إال مــن طريــق املدعــى عليــه ومنهــا‬\n‫عقــد اإليجــار وتعريــف براتبــه وفاتــورة هاتفــه ونحوهــا وكذلــك مــا‬\n‫وردنــا مــن مــرور الظهــران مــن أن الســيارة مســجله باســم املدعــى عليــه‬\n\n\n                                                                                              ‫‪74‬‬\n\f     ‫وكل ذلــك دال علــى أن إنــكاره غيــر صحيــح وقــد قــال ابــن القيم رحمه‬\n     ‫اهلل يف الطــرق احلكميــة صفحــة (‪ )11‬مــا نصــه ( وباجلملــة فالبينــة اســم‬\n     ‫لــكل مــا تبــن احلــق ويظهــره ومــن خصهــا بالشــاهدين أو األربعــة أو‬\n     ‫الشــاهد لــم يــوف مســماها حقــه ولــم تــأت البينــة قــط يف القــران مــرادا‬\n     ‫بهــا الشــاهدان وإمنــا أتــت مــرادا بهــا احلجــة والدليــل والبرهــان ) أ ‪ .‬ه ـ‬\n     ‫ولكــون الشــركة املدعيــة قدمــت بيانــا مبــا دفعــه املدعــى عليــه ومــا‬\n     ‫بقــي بذمتــه املبنــي علــى ســندات وفواتيــر موقعــه مــن املدعــى عليــه كمــا‬\n     ‫أن املدعــى عليــه اقــر يف اجللســة املؤرخــة يف ‪1433/02/23‬ه ـ أن جميــع‬\n     ‫التوقيعــات علــى األوراق املقدمــة لنــا صحيحــه وتعــود لــه كمــا أن جميــع‬\n     ‫األوراق مــن خطــاب التعريــف بالراتــب وعقــد اإليجــار وفاتــورة الهاتــف‬\n     ‫تعــود لــه ‪ ،‬فقــد ثبــت لــدي أن الســيارة نــوع كــورال موديــل ‪2006‬م رقــم‬\n     ‫اللوحــة ‪ ..............‬قــد انتقلــت مــن ملــك الشــركة ‪ ...............‬إلــى ملــك‬\n     ‫‪ .................‬وان الباقــي بذمتــه مــن قيمــة الســيارة مبلــغ ثمــان وأربعــون‬\n     ‫ألــف وأربعمائــة ريــال وألزمتــه بدفعهــا حــا ًال لشــركة املدعيــة وبــه‬\n     ‫حكمــت وبعــرض احلكــم علــى الطرفــن قــرر املدعــي وكالــة قناعتــه‬\n     ‫وقــرر املدعــى عليــه عــدم قناعتــه باحلكــم وجــرى إفهامــه بــأن عليــه‬\n     ‫مراجعــة احملكمــة خــال خمســة أيــام الســتالم صــورة مــن احلكــم ثــم‬\n     ‫تقــدمي الئحتــه االعتراضيــة خــال ثالثــن يــوم فــإذا لــم يقــدم اعتراضــه‬\n     ‫خــال املــدة احملــددة ســقط حقــه يف االعتــراض واكتســب احلكــم‬\n     ‫القطعيــة وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                   ‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/09/10‬ه ـ ‪.‬‬\n\n     ‫•صــدق احلكــم مــن محكمــة االســتئناف برقــم ‪3415623181‬‬\n                                        ‫وتاريــخ ‪1434/1/18‬هــ‪.‬‬\n\n‫‪75‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"17250706-b6cd-5618-b1f0-019e3dec82ff","source_page_start":70,"source_page_end":75,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"266d2d19851baf70fbfaf4ae4912cd4de747b606af72fb8bb277fcd1655587c4","normalized_text_hash":"4b84e0866af757229575c450764b97b8bad8c97ef04d20c6beab92b7fd4ee56f","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v1-p70-33408456"},{"id":"8ea2912a-4795-57cc-91a1-ebd6e3e08e90","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -بيع شرائح إتصاالت بآجل -املطالبة بدفع قيمة الشرائح -عدم حضور املدعى عليه -شهادة الشهود العدول -مين املدعي - احلكم غيابي ا بدفع الثمن -الغائب على حجته متى حضر .","document_number":"33303135","case_number":"4700","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالدمام","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/6/17","year":"1434","subject":"بيع -بيع شرائح إتصاالت بآجل -املطالبة بدفع قيمة الشرائح -عدم حضور املدعى عليه -شهادة الشهود العدول -مين املدعي - احلكم غيابي ا بدفع الثمن -الغائب على حجته متى حضر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1433/6/17 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪33303135 :‬‬\n                        ‫َر ْق ُم الدعوى‪4700 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34264753‬تاريخه‪1434/7/10 :‬هـ‬\n\n\n‫بيــع ‪ -‬بيــع شــرائح إتصــاالت بآجــل ‪ -‬املطالبــة بدفــع قيمــة الشــرائح‬\n‫‪ -‬عــدم حضــور املدعــى عليــه ‪ -‬شــهادة الشــهود العــدول ‪ -‬ميــن املدعــي ‪-‬‬\n      ‫احلكــم غيابيـ ًا بدفــع الثمــن ‪ -‬الغائــب علــى حجتــه متــى حضــر ‪.‬‬\n\n\n\n\n‫‪ -‬مــا ورد أن النبــي صلــى اهلل عليــه وســلم قــال ( لــو يعطــى النــاس‬\n‫بدعواهــم الدعــى رجــال دمــاء قــوم وأموالهــم ولكــن البينــة علــى املدعــي‬\n                                  ‫واليمــن علــى مــن أنكــر ) رواه البيهقــي ‪.‬‬\n              ‫‪ -‬املادة ‪/18‬ط و‪ 55‬و ‪ 4/176‬من نظام املرافعات الشرعية ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي أن املدعــى عليــه اشــترى منــه شــرائح اتصــاالت باآلجــل‬\n‫علــى أن يســلم املبلــغ خــال يومــن ومنــذ ذلــك احلــن لــم يســلم املبلــغ طلــب‬\n‫إلزامــه بدفــع مبلــغ قيمــة هــذه الشــرائح ‪ -‬أحضــر املدعــي شــاهدين‬\n‫كمــا حلــف اليمــن‪ ،‬لــم يحضــر املدعــى عليــه اجللســات‪ ،‬صــدر احلكــم‬\n‫غيابيـ ًا بدفــع قيمــة الشــرائح علمــا أن الغائــب علــى حجتــه متــى حضــر ‪-‬‬\n                                   ‫صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n                                                                                       ‫‪76‬‬\n\f     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .............‬القاضــي يف احملكمــة‬\n     ‫العامــة بالدمــام وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n     ‫احملكمــة العامــة بالدمــام برقــم ‪ 4700‬وتاريــخ ‪ 1430/07/05‬ه ـ‬\n     ‫املقيــدة باحملكمــة برقــم ‪ 3018428‬وتاريــخ ‪ 1430/07/05‬ه ـ ففــي‬\n     ‫يــوم االثنــن املوافــق ‪1433/01/10‬ه ـ افتتحــت اجللســة الســاعة التاســعة‬\n     ‫وفيهــا حضــر املدعــي ‪ ............‬ســوري اجلنســية مبوجــب اإلقامــة رقــم‬\n     ‫‪ .........‬ولــم يحضــر املدعــى عليــه ‪ ...............‬حيــث تعــذر إبالغــه باحلضــور‬\n     ‫مبوجــب األوراق الــواردة لنــا مــن رئيــس قســم محضــري اخلصــوم برقــم‬\n     ‫‪ 32939808‬يف ‪1432/10/23‬ه ـ لــذا جــرى رفــع اجللســة وذلــك للكتابــة‬\n     ‫ملقــام إمــارة املنطقــة الشــرقية إلبــاغ املدعــى عليــه مبوجــب املــادة ‪/18‬ط‬\n     ‫يف يــوم الســبت املوافــق ‪ 1433/03/12‬ه ـ افتتحــت اجللســة الســاعة ‪19‬‬\n     ‫‪ 10 :‬يف دعــوى ‪ ...........‬ضــد ‪ ............‬وفيهــا حضــر املدعــي ‪.............‬‬\n     ‫ولــم يحضــر املدعــى عليــه وقــد وردنــا خطــاب مــن وكيــل إمــارة املنطقــة‬\n     ‫الشرقية برقم ‪ 6456‬يف ‪1433/02/06‬هـ املوجه لسعادة مدير شرطة‬\n     ‫املنطقــة الشــرقية املتضمــن التعميــم بالبحــث عــن املدعــى عليــه حســب‬\n     ‫الطــرق املتبعــة وبنــاء علــى املــادة خمســة وخمســون مــن نظــام املرافعــات‬\n     ‫الشــرعية فســيجري ســماع الدعــوى غياب ـ ًا وبســؤال املدعــي عــن دعــواه‬\n     ‫قــال لقــد اشــترى منــي املدعــى عليــه الغائــب عــن مجلــس احلكــم شــرائح‬\n     ‫‪ ....‬باألجــل بقيمــة اثنــا وخمســون ألــف وســتمائة وخمســة وســتون ريــال‬\n     ‫علــى ان يســلمني املبلــغ خــال يومــن وذلــك بكفالــة شــخص مصــري‬\n     ‫اســمه ‪ .............‬ويعمــل مديــر مبيعــات شــركة ‪............‬ومنــذ ان اشــترى‬\n\n‫‪77‬‬\n\f‫منــي الشــرائح إلــى يومنــا هــذا لــم يســلمني املبلــغ اطلــب احلكــم عليــه‬\n‫والزامــه بدفــع قيمــة الشــرائح وقدرهــا اثنــان وخمســون الــف وســتمائة‬\n‫وخمســة وســتون ريــال هــذه دعــواي وبطلــب البينــة مــن املدعــي قــال‬\n‫اطلــب امهالــي إلحضارهــا ويف يــوم الثالثــاء املوافــق‪ 1433/06/10‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 08 : 34‬وفيهــا حضــر املدعــي ‪ ..............‬ولــم‬\n‫يحضــر املدعــى عليــه وبطلــب البينــة مــن املدعــي احضــر معــه للشــهادة‬\n‫‪ ............‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ..........‬وبســؤاله‬\n‫عــن بياناتــه ومــا لديــه مــن شــهادة قــال اســمي ‪ .........‬ابلــغ مــن العمــر اثنــان‬\n‫وعشــرون عام ـ ًا طالــب بجامعــة األميــر محمــد بــن فهــد واقيــم بصفــوى‬\n‫وليــس لــي قرابــه بطــريف النــزاع واشــهد أن ‪ ........‬مصــري اجلنســية جــاء‬\n‫إلــى مجمــع احليــاة بــازا وكنــت يف ذلــك اليــوم جالــس مــع ‪ ......‬وأقــر على‬\n‫أن يف ذمتــه لــ‪ .....‬مبلــغ اثنــان وخمســون الــف وســتمائة وخمســة وســتون‬\n‫ريــال قيمــة شــرائح اتصــال وكان يوجــد شــخص ســعودي ال أذكــر‬\n‫اســمه وقــد كفــل ‪ ....‬حيــث قــال (( فلــوس ‪ ..........‬عنــدي )) هــذا مــا‬\n‫لــدي مــن شــهادة ثــم أحضــر الشــاهد الثانــي فقــال اســمي ‪ ................‬ميني‬\n‫اجلنســية مبوجــب إقامــة رقــم ‪ ...............‬ابلــغ مــن العمــر واحــد وثالثــون‬\n‫ســنه واعمــل يف مجــال بيــع وإصــاح اجلــوالت واقيــم يف مخطــط ‪/ 91‬‬\n‫ج بالدمــام وال يوجــد قرابــه بــن طــريف النــزاع واشــهد أن ‪ .........‬مصــري‬\n‫اجلنســية جــاء إلــى محــل ‪ ...........‬وكنــت موجــود حيــث أقــر ‪ ....‬أن يف‬\n‫ذمتــه ل‪ ........‬مبلــغ اثنــان وخمســون الــف وســتمائة وخمســة وســتون ريــال‬\n‫قيمــة شــرائح ســوا ثــم حصــل لقــاء آخــر يف مجمــع ‪ .....‬حيــث حضــر‬\n‫مــع ‪ ....‬شــخص ســعودي ال اعــرف اســمه قــال بأنــه كفيــل ‪...............‬‬\n‫وقــد أقــر ‪ ....‬أن يف ذمتــه ل‪ .........‬مبلــغ اثنــان وخمســون الــف وســتمائة‬\n\n                                                                                              ‫‪78‬‬\n\f     ‫وخمســة وســتون ريــال وقــد رفــض أن يكتــب ورقــة بذلــك هــذا مــا لــدي‬\n     ‫مــن شــهادة وبطلــب تعديلهمــا حضــر كال مــن ‪ .....................‬ســوري‬\n     ‫اجلنســية مبوجــب اإلقامــة رقــم ‪ .....................‬و ‪ ....................‬ســوري‬\n     ‫اجلنســية مبوجــب اإلقامــة رقــم ‪ ...................‬وبســؤالهما عــن الشــاهدين‬\n     ‫قــال كل واحــد منهمــا منفــرد ًا أنهمــا مــن أهــل اخليــر والصــاح نحســبه‬\n     ‫كذلــك واهلل حســيبه ففــي يــوم الثالثــاء املوافــق‪ 1433/06/17‬ه ـ‬\n     ‫افتتحــت اجللســة الســاعة ‪ 09 : 04‬وفيهــا حضــر املدعــي ‪...................‬‬\n     ‫ولــم يحضــر املدعــى عليــه فبنــاء علــى الدعــوى واالجابــة وجميــع مــا‬\n     ‫تقــدم ونظــرا لكــون املدعــي قــدم بينتــه املعدلــة واملتضمنــة أن يف ذمــة‬\n     ‫املدعــى عليــه ‪ ..............‬مبلــغ اثنــان وخمســون الــف وســتمائة وخمســة‬\n     ‫وســتون ريــاال قيمــة شــرائح اتصــال لصالــح املدعــي ‪ ...........‬وقــد جــاء يف‬\n     ‫ســن البيهقــي أن النبــي صلــى اهلل عليــه وســلم قــال ( لــو يعطــى النــاس‬\n     ‫بدعواهــم الدعــى رجــال دمــاء قــوم وأموالهــم ولكــن البينــة علــى املدعــي‬\n     ‫واليمــن علــى مــن أنكــر ) عليــه فقــد ثبــت لــدي أن يف ذمــة املدعــى‬\n     ‫عليــه الغائــب عــن مجلــس احلكــم ‪ ..............‬مبلــغ اثنــان وخمســون الــف‬\n     ‫وســتمائة وخمســة وســتون ريــاال قيمــة شــرائح اتصــال يدفعهــا حــاال‬\n     ‫للمدعــي ‪ .............‬وبــه حكمــت علمــا أن الغائــب علــى حجتــه متى حضر‬\n     ‫وبعــرض احلكــم علــى املدعــي قــرر قناعتــه ورضــاه بــه ولكــون احلكــم‬\n     ‫غيابيــا يف حــق املدعــى عليــه فســيجري تبليغــه حســب الطــرق املتبعــة‬\n     ‫حســب املــادة ‪ 4/176‬مــن نظــام املرافعــات الشــرعية‪ .‬وبــاهلل التوفيــق ‪،‬‬\n                         ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n     ‫ويف يــوم االثنــن املوافــق ‪1433/01/10‬ه ـ افتتحــت اجللســة الســاعة‬\n     ‫التاســعة وفيهــا حضــر املدعــي ‪ ................‬ســوري اجلنســية مبوجــب‬\n\n\n‫‪79‬‬\n\f‫اإلقامــة رقــم ‪ ...................‬ولــم يحضــر املدعــى عليــه ‪ .................‬حيــث‬\n‫تعــذر إبالغــه باحلضــور مبوجــب األوراق الــواردة لنــا مــن رئيــس قســم‬\n‫محضــري اخلصــوم برقــم ‪ 32939808‬يف ‪1432/10/23‬ه ـ لــذا جــرى‬\n‫رفــع اجللســة وذلــك للكتابــة ملقــام إمــارة املنطقــة الشــرقية إلبــاغ املدعى‬\n‫عليــه مبوجــب املــادة ‪/18‬ط ورفعــت اجللســة إلــى يــوم الســبت املوافــق‬\n‫‪1433/3/12‬ه ـ الســاعة العاشــرة صباحــا وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1433/01/10‬ه ـ‬\n‫يف يــوم االثنــن املوافــق‪ 1434/05/27‬ه ـ افتتحــت اجللســة الســاعة‬\n‫العاشــرة صباحـ ًا وقــد وردتنــا أوراق املعاملــة مــن محكمــة االســتئناف‬\n‫برقــم ‪ 34521109‬يف ‪1434/04/14‬ه ـ مرفق ـ ًا بهــا القــرار رقــم‬\n‫‪ 34180975‬يف ‪1434/04/07‬ه ـ والصــادر مــن قضــاة دائــرة األحــوال‬\n‫الشــخصية الثانيــة واملتضمــن ( وبدراســة الصــك وصــورة ضبطــه وأوراق‬\n‫املعاملــة لوحــظ باألكثريــة أن املدعــي احضــر الشــاهدين املذكوريــن‬\n‫الذيــن شــهدا بكامــل املبلــغ املدعــى بــه لكــن ال يعلــم هــل ســدد املدعــى‬\n‫عليــه شــيئ ًا منــه أم ال لــذا فيتعــن طلــب ميــن املدعــي علــى نفــي ذلــك‬\n‫فعلــى فضيلتــه مالحظــة مــا أشــير إليــه واحلــاق مــا يجــد يف الصــك‬\n‫وضبطــه وســجله ومــن ثــم إعــادة املعاملــة إلكمــال الزمهــا واهلل املوفــق‬\n‫) أ ‪.‬ه ـ رئيــس الدائــرة ‪ ............‬ختمــه وتوقيعــه قاضــي اســتئناف ‪.............‬‬\n‫ختمــه وتوقيعــه قاضــي اســتئناف ‪ ............‬ختمــه وتوقيعــه ‪ ،‬ويف هــذه‬\n‫اجللســة حضــر املدعــي ‪ .........‬ونظــر ًا لوجاهــة املالحظــة وبعــد تخويــف‬\n‫املدعــي بــاهلل عــز وجــل فقــال أنــا مســتعد بــأداء اليمــن علــى أن املدعــى‬\n‫عليــه لــم يســدد شــيء مــن املبلــغ املدعــى بــه فقــال ( واهلل العظيــم ثــم‬\n‫واهلل العظيــم ثــم واهلل العظيــم أن ‪ ............‬لــم يســدد مــا يف ذمتــه وقــدره‬\n\n\n                                                                                           ‫‪80‬‬\n\f     ‫اثنــان وخمســون ألــف وســتمائة وخمســة وســتون ريــال وان كامــل‬\n     ‫املبلــغ مــا يــزال عنــده) بنــاء عليــه ســيجري إعــادة كامــل أوراق املعاملــة‬\n     ‫إلــى محكمــة االســتئناف بعــد التهميــش علــى صكــه وســجله وبــاهلل‬\n     ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                 ‫حــرر يف ‪ 1434/05/27‬ه ـ ‪.‬‬\n\n\n\n     ‫•صــدق احلكــم مــن محكمــة االســتئناف برقــم ‪ 34264753‬وتاريــخ‬\n                                                     ‫‪1434/7/10‬هـ‪.‬‬\n\n\n\n\n‫‪81‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"17250706-b6cd-5618-b1f0-019e3dec82ff","source_page_start":76,"source_page_end":81,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"75d1787b2342a42e9b87fdd1cc99706dde9fa131d47adb4336919a0a1cb3ae22","normalized_text_hash":"acfd97cb3220646f9b7b041c25bcdb4e74cdae953b3575a542001427f7f94811","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v1-p76-33303135"}]$archive_payload$::jsonb AS data)
